  if(doneBtn)doneBtn.onclick=()=>{closeWheelSheet()};
  document.body.classList.add("is-sheet-open");
  openModal(sheet,{initialFocus:col,returnFocus:btn,onEscape:closeWheelSheet,scrim,delayHide:reducedMotion()?0:280});
  wheelDrum?.destroy();
