            const rebased=editorRebaseDocument({edits},lockedHead);
            if(rebased.conflict)
              return{reject:true,result:{ok:false,conflict:true,editorConflict:true,code:rebased.code}};
            const lockedOptIn=confirmOptIn(rebased.document);
