// @ci-domain global
let shareSetupReturn=null,shareSetupLink="",shareSetupBlockers=[],shareRepairReturn=null,shareRepairFocusIntent=null;
function shareSetupBlockerMessage(count){
  const n=Number(count)||0;
  const form=n===1?"one":"other";
  return t(`program.share_setup_blocked.${form}`,{n});
}
function renderShareSetupBlockers(){
  const summary=$("#shareSetupBlockerSummary"),list=$("#shareSetupBlockers");
  const blockers=Array.isArray(shareSetupBlockers)?shareSetupBlockers:[];
  if(summary){summary.textContent=blockers.length?shareSetupBlockerMessage(blockers.length):"";summary.classList.toggle("hidden",!blockers.length)}
  if(!list)return;
  list.classList.toggle("hidden",!blockers.length);
  list.innerHTML=blockers.map(blocker=>{
    const id=String(blocker?.exerciseInstanceId??"");
    const name=blocker?.displayName||t("program.share_setup_exercise");
    const reason=tOr(`program.share_setup_reason.${blocker?.reasonCode}`,t("program.share_setup_reason.unknown"));
    return `<div class="share-setup__blocker" data-share-blocker-id="${esc(id)}" data-share-day-id="${esc(blocker?.dayId||"")}" data-share-reason="${esc(blocker?.reasonCode||"")}" role="listitem">`+
      `<div class="share-setup__blocker-copy"><strong>${esc(name)}</strong>`+
      `<span>${esc(reason)}</span></div>`+
      `<button type="button" class="btn btn--steel share-setup__repair" data-share-repair="${esc(id)}" aria-label="${esc(t("program.share_setup_repair_aria",{name}))}">${esc(t("program.share_setup_repair"))}</button></div>`;
  }).join("");
  $$("#shareSetupBlockers [data-share-repair]").forEach(button=>button.onclick=()=>beginShareRepair(button.dataset.shareRepair));
}
function setShareSetupState(message,{ready=false,blockers=null,fileFallback=false}={}){
  if(blockers!==null)shareSetupBlockers=Array.isArray(blockers)?blockers:[];
  renderShareSetupBlockers();
  const blocked=shareSetupBlockers.length>0;
  ready=ready&&!blocked;
  const status=$("#shareSetupStatus"),out=$("#shareSetupLink"),share=$("#shareSetupShare"),copy=$("#shareSetupCopy"),file=$("#shareSetupFile");
  // A program too large for a link can still travel whole as a program file.
  if(file){file.disabled=!fileFallback;file.classList.toggle("hidden",!fileFallback)}
  const body=$("#shareSetupBody");if(body)body.classList.toggle("hidden",fileFallback);
  if(status){status.textContent=message||"";status.classList.toggle("hidden",!message)}
  if(out){if("value" in out)out.value=ready?shareSetupLink:"";else out.textContent=ready?shareSetupLink:""}
  if(share){share.disabled=!ready||typeof navigator.share!=="function";share.classList.toggle("hidden",!ready||typeof navigator.share!=="function")}
  if(copy){copy.disabled=!ready;copy.classList.toggle("hidden",!ready)}
}
/* Plan 076 (owner option A): an unedited program generated before the 073.5
   bump would still be a short recipe link, but a link now regenerates under the
   current version, so it travels as a file until the next block, which this
   version generates. Only that exact case is told the link comes back. */
function shareSetupWaitsForNextBlock(definition){
  const versions=ProgramCompiler?.BASELINE_VERSIONS||[];
  if(definition?.provenance?.source!=="recovered_generation_rules"||!versions.includes(definition.generatorVersion))return false;
  try{
    const request=cloneSnapshot(definition.request);delete request.seed;
    const regenerated=ProgramCompiler.generateProgram(request,rawExerciseCatalog,{asVersion:definition.generatorVersion});
    return regenerated?.ok===true&&JSON.stringify(canonicalize(regenerated.value))===JSON.stringify(canonicalize(definition))}
  catch{return false}}
function sharedSetupErrorMessage(result,definition=null){
  if(result?.code==="unresolved-exercises")return shareSetupBlockerMessage(result.blockers?.length||0);
  if(result?.code==="compression-unavailable")return t("program.share_setup_unsupported");
  if(result?.code==="encoded-too-large")return t(shareSetupWaitsForNextBlock(definition)?"program.share_setup_next_block":"program.share_setup_too_large");
  return t("program.share_setup_invalid")}
/* Coarse facts about a setup-link attempt for telemetry: the kind of program,
   the form the codec used, and its size against the link limit. The event's
   forms are frozen (owner, 2026-10-30), so a recipe-plus-edits link (#527)
   reports form "recipe" with program_kind "generated_edited": only it makes
   that pair. */
let shareSetupOutcome=null;
function shareSetupTelemetry(definition,encoded){
  const generated=definition?.provenance?.source!=="manual"&&typeof definition?.request?.goal==="string";
  const form=encoded?.form==="recipe"||encoded?.form==="patch"?"recipe":"full";
  const program_kind=definition?.provenance?.source==="manual"?"manual":generated?(encoded?.form==="recipe"?"generated":"generated_edited"):"other";
  const limit=SharedSetup?.MAX_ENCODED_CHARS||3072,chars=Number(encoded?.encodedChars);
  const ratio=Number.isFinite(chars)?chars/limit:Infinity;
  const size_vs_limit=ratio<=.5?"under_half":ratio<=1?"under_limit":ratio<=2?"over_limit":ratio<=4?"over_2x":"over_4x";
  return{program_kind,form,size_vs_limit}}
async function buildShareSetupLink(){
  shareSetupLink="";shareSetupOutcome=null;
  setShareSetupState(t("program.share_setup_building"),{blockers:[]});
  if(!SharedSetup){setShareSetupState(t("program.share_setup_unsupported"));return}
  let built;
  try{built=buildSharedSetupValidation()}catch{setShareSetupState(t("program.share_setup_invalid"));return}
  const checked=SharedSetup.validate(built.payload,{...sharedSetupCodecOptions(),diagnostics:built.diagnostics});
  if(!checked.ok){setShareSetupState(sharedSetupErrorMessage(checked),{blockers:checked.blockers||[]});return}
  let encoded;
  try{encoded=await SharedSetup.encode(checked.value,sharedSetupCodecOptions())}
  catch{setShareSetupState(t("program.share_setup_unsupported"));return}
  shareSetupOutcome=shareSetupTelemetry(checked.value.program.definition,encoded);
  if(!encoded.ok){
    const tooLarge=encoded.code==="encoded-too-large";
    if(tooLarge)captureEvent("share_setup_outcome",{action:"link_refused",...shareSetupOutcome});
    setShareSetupState(sharedSetupErrorMessage(encoded,checked.value.program.definition),{fileFallback:tooLarge});return}
  captureEvent("share_setup_outcome",{action:"link_ready",...shareSetupOutcome});
  const local=/^(localhost|127(?:\.\d{1,3}){3}|\[::1\])$/i.test(location.hostname);
  const url=new URL("index.html",local?location.href:"https://pedrochagasmaster.github.io/repforge/index.html");
  url.search="";
  url.hash=`setup=${encoded.value}`;
  shareSetupLink=url.href;
  setShareSetupState("",{ready:true,blockers:[]})}
function shareRepairToken(){
  return{surface:"share",programId:state?.programMeta?.id||null,blockId:snapshotBlockId(state),exerciseInstanceId:null};
}
function shareRepairTargetMatches(token,snapshot=state){
  return !!token&&token.programId===(snapshot?.programMeta?.id||null)&&token.blockId===snapshotBlockId(snapshot)&&
    Array.isArray(snapshot?.program)&&snapshot.program.some(ex=>ex?.id===token.exerciseInstanceId);
}
function shareSetupRepairButton(id){
  return $$("#shareSetupBlockers [data-share-repair]").find(button=>button.dataset.shareRepair===id)||null}
function focusShareSetupRepair(token){
  const remaining=$$("#shareSetupBlockers [data-share-repair]");
  const exact=token?.exerciseInstanceId?shareSetupRepairButton(token.exerciseInstanceId):null;
  const target=[exact,...remaining,$("#shareSetupBlockerSummary"),$("#shareSetupStatus"),$("#shareSetupCopy"),$("#shareSetupClose")].find(canTakeFocus);
  if(canTakeFocus(target)){
    try{target.focus({preventScroll:true})}catch{try{target.focus()}catch{}}
    if(target.matches("[data-share-repair]")){
      const body=$("#shareSetupSheet .sheet__body");
      if(body){
        const maxScroll=Math.max(0,body.scrollHeight-body.clientHeight);
        body.scrollTop=maxScroll;
        const bodyRect=body.getBoundingClientRect(),targetRect=target.getBoundingClientRect();
        const bodyTop=bodyRect.top+body.clientTop,bodyBottom=bodyTop+body.clientHeight;
        if(targetRect.top<bodyTop||targetRect.bottom>bodyBottom){
          const targetCenter=targetRect.top-bodyTop+body.scrollTop+targetRect.height/2;
          body.scrollTop=Math.max(0,Math.min(maxScroll,targetCenter-body.clientHeight/2))
        }
      }
    }
  }}
function reopenShareAfterRepair(){
  const token=shareRepairReturn;
  shareRepairReturn=null;
  if(!token)return;
  shareRepairFocusIntent=token;
  queueMicrotask(()=>{
    if(shareRepairFocusIntent===token)openShareSetupSheet({repairFocus:token})});
}
async function beginShareRepair(exerciseInstanceId){
  const id=String(exerciseInstanceId||"");
  const blocker=shareSetupBlockers.find(item=>String(item?.exerciseInstanceId??"")===id);
  if(!blocker)return;
  shareRepairReturn={...shareRepairToken(),exerciseInstanceId:id};
  const closed=closeShareSetupSheet();
  if(closed&&typeof closed.then==="function")await closed;
  if(!shareRepairReturn)return;
  if(!shareRepairTargetMatches(shareRepairReturn,state)){finishInstalledEditor({discard:true});return}
  programEditMode=true;
  renderProgram();
  const editor=installedProgramEditor;
  if(!editor){finishInstalledEditor({discard:true});return}
  const result=await editor.replaceExercise(id);
  if(!result||result.ok===false||result.cancelled){finishInstalledEditor({discard:true});return}
  await applyInstalledEditorAndContinue();
}
function openShareSetupSheet({repairFocus=null}={}){
  const sheet=$("#shareSetupSheet"),scrim=$("#shareSetupScrim");
  if(!sheet)return;
  if(!repairFocus)shareRepairFocusIntent=null;
  const subtitle=$("#shareSetupFor");if(subtitle)subtitle.textContent=state.programMeta?.name||t("untitled_program");
  shareSetupReturn=document.activeElement;
  document.body.classList.add("is-sheet-open");
  openModal(sheet,{initialFocus:repairFocus?()=>shareSetupRepairButton(repairFocus.exerciseInstanceId)||$("#shareSetupClose"):$("#shareSetupClose"),returnFocus:shareSetupReturn,
    onEscape:closeShareSetupSheet,scrim,delayHide:reducedMotion()?0:280});
  requestAnimationFrame(()=>{sheet.classList.add("is-open");scrim?.classList.add("is-open")});
  buildShareSetupLink().then(()=>{
    if(repairFocus&&shareRepairFocusIntent===repairFocus&&activeModal?.el===sheet){
      shareRepairFocusIntent=null;
      focusShareSetupRepair(repairFocus)}})}
function closeShareSetupSheet(){
  const sheet=$("#shareSetupSheet");
  if(!sheet)return Promise.resolve(false);
  if(sheet.hidden&&!(activeModal&&activeModal.el===sheet))return Promise.resolve(false);
  shareSetupReturn=null;
  return closeModal(sheet)}
async function copySetupLink(){
  if(!shareSetupLink||shareSetupBlockers.length)return false;
  try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(shareSetupLink);
    toast(t("toast.setup_link_copied"));if(shareSetupOutcome)captureEvent("share_setup_outcome",{action:"copied",...shareSetupOutcome});return true}}catch{}
  try{const ta=document.createElement("textarea");ta.value=shareSetupLink;ta.setAttribute("readonly","");
    ta.style.cssText="position:fixed;top:0;left:0;opacity:0";document.body.append(ta);ta.select();
    const ok=document.execCommand("copy");ta.remove();
    if(ok){toast(t("toast.setup_link_copied"));if(shareSetupOutcome)captureEvent("share_setup_outcome",{action:"copied",...shareSetupOutcome});return true}}catch{}
  return false}
async function shareSetupLinkNow(){
  if(!shareSetupLink||shareSetupBlockers.length||typeof navigator.share!=="function")return false;
  try{await navigator.share({title:t("program.share_setup_title"),url:shareSetupLink});if(shareSetupOutcome)captureEvent("share_setup_outcome",{action:"shared",...shareSetupOutcome});return true}
  catch{return false}}
/* ============================================================
   Exercise picker
   One sheet, three callers: the program editor's add and change
   paths, and the log-tab substitution.
   Callers hand it a mode and a callback and get library entries
   back — they never touch the library themselves, so a movement
   arrives in a program slot the same way from every surface.
   ============================================================ */

/* Search is accent- and case-blind, and reads both languages at once: a
   Portuguese lifter still types "bench press" for a machine whose plate says
   so, and an English one still finds "supino". */
const foldSearch=s=>String(s??"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
const MUSCLE_TOKENS=window.RepForgeProgramEntry.MUSCLE_TOKENS;
const PICKER_EQUIPMENT=window.RepForgeProgramEntry.KNOWN_EQUIPMENT;
/* Muscle filters lifters actually think in, each covering the tokens under it. */
const PICKER_MUSCLE_GROUPS=Object.freeze([
  ["chest",["Chest"]],
  ["back",["Lats","Mid/upper back","Traps"]],
  ["shoulders",["Front delts","Side delts","Rear delts"]],
  ["arms",["Biceps","Triceps","Forearms"]],
  ["legs",["Quads","Hamstrings","Glutes","Adductors","Abductors","Calves"]],
  ["core",["Abs","Obliques","Spinal erectors"]],
]);

let pickerState=null,pickerReturn=null,customState=null,customReturn=null;

const exerciseSearchText=e=>foldSearch(`${e.name} ${e.namePt||""} ${e.primary||""} ${e.secondary||""}`);
function exerciseMatches(e,query,muscleGroup,equipment){
  if(equipment&&!(e.equipment||[]).includes(equipment))return false;
  if(muscleGroup){
    const group=PICKER_MUSCLE_GROUPS.find(g=>g[0]===muscleGroup);
    const tokens=`${e.primary||""},${e.secondary||""}`.split(",");
    if(group&&!tokens.some(x=>group[1].includes(x)))return false}
  if(!query)return true;
  const hay=exerciseSearchText(e);
  return foldSearch(query).split(/\s+/).filter(Boolean).every(w=>hay.includes(w))}

/* Library ids already in the program, and names already logged. Both float to
   the top of the list: the movement somebody wants next is usually one they
   have met before. */
function programLibraryIds(){
  const ids=new Set();
  for(const e of state.program||[])if(e.libraryId)ids.add(String(e.libraryId));
  return ids}
/* What the lifter has actually trained, for promoting familiar movements in the
   picker. Library ids are the reliable half — names only match when the log was
   written in the language the picker is being read in. */
function loggedExerciseRefs(){
  const ids=new Set(),names=new Set();
  for(const r of state.log||[]){
    if(r?.performedLibraryId)ids.add(String(r.performedLibraryId));
    if(r?.performedName)names.add(foldSearch(r.performedName));
    if(r?.name)names.add(foldSearch(r.name))}
  for(const e of state.program||[])if(e.libraryId)ids.add(String(e.libraryId));
  return{ids,names}}

/* ---- Exercise artwork ----
   Twenty-four movements have licensed illustrations; every other built-in and
   every custom exercise renders a deliberately empty tile. The empty state is
   an element with no src, not an <img> pointing at a file that is not there:
   a broken-image request is both a wasted fetch and a visible glyph. Both
   shapes are the same size so a mixed list stays aligned. */
const exerciseMedia=e=>(e&&typeof e.media==="string"&&e.media)||null;
/* The paper colour the illustration is drawn on, sampled per file at build time
   (tools/sample-media-bg.mjs). The detail page lays the artwork on a field of
   this colour so the opaque square dissolves rather than reading as a pasted
   tile. Re-checked here because the value reaches a style attribute, and a
   generated file is still a file somebody can edit. */
const HEX_COLOR=/^#[0-9a-f]{6}$/i;
const exerciseMediaBg=e=>(e&&typeof e.mediaBg==="string"&&HEX_COLOR.test(e.mediaBg)&&e.mediaBg)||null;
/* A program slot and an identity recovered from a log row both carry a library
   id rather than the artwork itself, so the illustration has to come from the
   definition they point at. A custom entry resolves too and simply has none. */
const exerciseRefEntry=ref=>ref?.libraryId!=null?libraryEntry(ref.libraryId):ref;
const emptyThumb=({size="md"}={})=>
  `<span class="exthumb exthumb--${esc(size)} exthumb--empty" aria-hidden="true"><span class="icon-mask icon-mask--dumbbell"></span></span>`;
function exerciseThumb(e,{size="md"}={}){
  const src=exerciseMedia(e);
  if(!src)return emptyThumb({size});
  // alt is empty on purpose: the exercise name sits next to it in every list,
  // so describing the drawing again would only repeat the row to a screen reader.
  return `<img class="exthumb exthumb--${esc(size)}" src="${esc(src)}" alt="" `+
    `loading="lazy" decoding="async" width="768" height="768">`}

function pickerRow(e,{selected=false,checkbox=false}={}){
  const muscles=[e.primary,e.secondary].filter(Boolean).join(",").split(",").filter(Boolean);
  const shown=muscles.slice(0,3).map(muscleLabel);
  const eq=(e.equipment||[])[0]||null;
  return `<button type="button" class="pickrow${selected?" is-selected":""}" data-pick="${esc(e.id)}"`+
    (checkbox?` role="checkbox" aria-checked="${selected?"true":"false"}"`:"")+`>`+
    exerciseThumb(e,{size:"sm"})+
    `<span class="pickrow__main">`+
      `<span class="pickrow__name">${esc(libraryName(e))}</span>`+
      `<span class="pickrow__meta">${esc(shown.join(" · "))}</span>`+
    `</span>`+
    (eq?`<span class="pickrow__eq">${esc(t("picker.equipment."+eq))}</span>`:"")+
    `<span class="pickrow__tick" aria-hidden="true"></span>`+
  `</button>`}

/* The swap sheet's optional reason (Plan 071 §10): one tap, none by default,
   and picking an exercise never waits on it. The chips lead the scrolling list
   rather than the fixed tools, so enlarged text can never crowd the list out. */
const SUBSTITUTION_REASONS=Object.freeze(["equipment","preference","pain","crowded","other"]);
const SUBSTITUTION_REASON_LABELS=Object.freeze({equipment:"picker.reason.equipment",preference:"picker.reason.preference",
  pain:"picker.reason.pain",crowded:"picker.reason.crowded",other:"picker.reason.other"});
function renderPickerReasons(){
  const el=$("#exPickReasons");if(!el)return;
  const reasons=pickerState?.reasons;
  if(!reasons){el.innerHTML="";return}
  el.innerHTML=`<p class="pick__reasons-label" id="exPickReasonsLabel">${esc(t("picker.reason_label"))}</p><div class="pick__reasons-chips">`+
    reasons.map(reason=>{const on=pickerState.reason===reason;
      return `<button type="button" class="pchip${on?" is-active":""}" data-pick-reason="${reason}" aria-pressed="${on}">${esc(t(SUBSTITUTION_REASON_LABELS[reason]))}</button>`}).join("")+`</div>`;
  el.querySelectorAll("[data-pick-reason]").forEach(button=>button.onclick=()=>{
    const reason=button.dataset.pickReason;
    pickerState.reason=pickerState.reason===reason?null:reason;
    renderPickerReasons();
    el.querySelector(`[data-pick-reason="${reason}"]`)?.focus()})}
function renderPickerFilters(){
  const el=$("#exPickFilters");if(!el||!pickerState)return;
  const chip=(kind,val,label,active)=>
    `<button type="button" class="pchip${active?" is-active":""}" data-filter="${kind}" data-val="${esc(val)}" aria-pressed="${active?"true":"false"}">${esc(label)}</button>`;
  const parts=[chip("clear","",t("picker.filter_all"),!pickerState.muscle&&!pickerState.equipment)];
  for(const [key] of PICKER_MUSCLE_GROUPS)
    parts.push(chip("muscle",key,t("picker.group."+key),pickerState.muscle===key));
  for(const eq of PICKER_EQUIPMENT)
    parts.push(chip("equipment",eq,t("picker.equipment."+eq),pickerState.equipment===eq));
  el.innerHTML=parts.join("");
  $$("#exPickFilters .pchip").forEach(b=>b.onclick=()=>{
    const kind=b.dataset.filter;
    if(kind==="clear"){pickerState.muscle=null;pickerState.equipment=null}
    else if(kind==="muscle")pickerState.muscle=pickerState.muscle===b.dataset.val?null:b.dataset.val;
    else pickerState.equipment=pickerState.equipment===b.dataset.val?null:b.dataset.val;
    renderPickerFilters();renderPickerList()})}

const pickerCandidates=()=>(pickerState?.extras||[]).concat(pickableExercises());
const pickerEntry=id=>pickerCandidates().find(e=>e.id===id)||libraryEntry(id);

function renderPickerList(){
  const el=$("#exPickList");if(!el||!pickerState)return;
  const {query,muscle,equipment,mode,selected,exclude}=pickerState;
  const multi=mode==="multi";
  // A quick-add tab narrows the source; typing in it searches everything,
  // because a lifter who types a name wants that name, not the tab.
  const source=pickerState.quick&&!query?libTabList(pickerState.tab):pickerCandidates();
  const matches=e=>!!e&&!exclude.has(e.id)&&exerciseMatches(e,query,muscle,equipment);
  // A caller's leading group (the swapped slot's alternates) keeps its own
  // order and is not repeated in the groups below it.
  const leading=pickerState.quick?[]:pickerState.leading.ids.map(pickerEntry).filter(matches);
  const leadingIds=new Set(leading.map(e=>e.id));
  const all=source.filter(e=>!leadingIds.has(e.id)&&matches(e));
  const inProgram=programLibraryIds(),logged=loggedExerciseRefs();
  const custom=[],known=[],rest=[];
  const familiar=e=>inProgram.has(e.id)||logged.ids.has(e.id)||
    logged.names.has(foldSearch(e.name))||logged.names.has(foldSearch(e.namePt||""));
  for(const e of all){
    if(isCustomLibraryId(e.id)||e.nameOnly)custom.push(e);
    else if(familiar(e))known.push(e);
    else rest.push(e)}
  // Rank before name. Alphabetical alone answers "row" with four barbell
  // variants before plain Barbell row, and opens the library on an assisted
  // kneeling dip — the staple for a movement should lead its own results.
  rest.sort((a,b)=>(a.rank??50)-(b.rank??50)||libraryName(a).localeCompare(libraryName(b)));
  const section=(key,list)=>list.length
    ?`<p class="pick__section">${esc(t(key))}</p>`+list.map(e=>pickerRow(e,{selected:selected.has(e.id),checkbox:multi})).join("")
    :"";
  const html=pickerState.quick&&!query
    ?(all.length?`<p class="pick__section">${esc(t("picker.tab_head."+pickerState.tab))}</p>`+
      all.map(e=>pickerRow(e,{selected:selected.has(e.id),checkbox:multi})).join(""):"")
    :section(pickerState.leading.title,leading)+
      section("picker.section_custom",custom)+
      section("picker.section_known",known)+
      section("picker.section_all",rest);
  el.innerHTML=(pickerState?.reasons?`<div id="exPickReasons" class="pick__reasons" role="group" aria-labelledby="exPickReasonsLabel"></div>`:"")+
    (html||`<p class="pick__empty">${esc(t("picker.empty",{q:query}))}</p>`);
  renderPickerReasons();
  $$("#exPickList .pickrow").forEach(b=>b.onclick=()=>choosePicked(b.dataset.pick));
  const done=$("#exPickDone");
  if(done)done.textContent=multi&&selected.size?t("picker.done_count",{n:selected.size}):t("dialog.done")}

async function choosePicked(id){
  if(!pickerState||pickerState.choosing)return;
  const entry=pickerEntry(id);
  if(!entry)return;
  if(pickerState.mode==="multi"){
    if(pickerState.selected.has(id))pickerState.selected.delete(id);
    else pickerState.selected.add(id);
    renderPickerList();return}
  const active=pickerState,handler=active.onPick;
  active.choosing=true;
  active.completed=true;
  const sheet=$("#exPickSheet");if(sheet)sheet.setAttribute("aria-busy","true");
  try{if(handler)await handler(entry);await closeExercisePicker();focusEntryEditorStatus()}
  finally{if(pickerState===active)active.choosing=false;if(sheet)sheet.removeAttribute("aria-busy")}}

/* mode "single" fires onPick with one entry and closes; "multi" collects and
   fires once on Done with the entries in selection order. */
function openExercisePicker({title=null,subtitle="",mode="single",selected=[],exclude=[],extras=[],onPick=null,
  onCancel=null,stageOnly=false,repairSeed=null,quick=false,day:dayName=null,query="",muscle=null,equipment=null,tab=null,
  leading=null,catalogOnly=false,reasons=null,returnFocus=null}={}){
  const sheet=$("#exPickSheet"),scrim=$("#exPickScrim"),search=$("#exPickSearch");
  if(!sheet)return;
  pickerState={query:String(query||""),muscle,equipment,mode,onPick,onCancel,stageOnly,repairSeed,completed:false,
    selected:new Set(selected.filter(Boolean).map(String)),
    exclude:new Set(exclude.filter(Boolean).map(String)),
    extras:extras.filter(Boolean),
    leading:{title:leading?.title||"",ids:(leading?.ids||[]).filter(Boolean).map(String)},
    quick,day:dayName,tab:quick&&(LIB_TABS.includes(tab)?tab:"suggested"),
    reasons:Array.isArray(reasons)?reasons:null,reason:null,
    // Kept so the custom-exercise detour can put this exact picker back, with
    // whatever was typed and filtered still in place.
    reopen:{title,subtitle,mode,exclude:[...exclude],extras:[...extras],onPick,onCancel,stageOnly,repairSeed,quick,day:dayName,leading,catalogOnly,reasons,returnFocus}};
  pickerReturn=returnFocus||document.activeElement;
  $("#exPickTitle").textContent=title||t("picker.title");
  const sub=$("#exPickFor");if(sub)sub.textContent=subtitle||"";
  if(search)search.value=pickerState.query;
  const done=$("#exPickDone");
  if(done)done.classList.toggle("hidden",mode!=="multi");
  const tabs=$("#exPickTabs");if(tabs)tabs.classList.toggle("hidden",!quick);
  const full=$("#exPickFull");if(full)full.classList.toggle("hidden",!quick);
  const custom=$("#exPickCustom");if(custom)custom.classList.toggle("hidden",setupEditorOpen||catalogOnly);
  if(quick)renderQuickTabs();
  renderPickerFilters();renderPickerList();
  document.body.classList.add("is-sheet-open");
  // The sheet takes focus, not the search box: focusing an input raises the
  // software keyboard, which covers half the phone before the lifter has asked
  // to type — and browsing the list is the common move, typing the rarer one.
  // The dialog element carries tabindex="-1" so it can hold focus without
  // joining the tab order, and Tab from it lands on the sheet's first control.
  openModal(sheet,{initialFocus:sheet,returnFocus:pickerReturn,onEscape:closeExercisePicker,scrim,
    delayHide:reducedMotion()?0:280});
  requestAnimationFrame(()=>{sheet.classList.add("is-open");scrim?.classList.add("is-open")})}

function closeExercisePicker(){
  const sheet=$("#exPickSheet");
  if(!sheet)return Promise.resolve(false);
  if(sheet.hidden&&!(activeModal&&activeModal.el===sheet))return Promise.resolve(false);
  const active=pickerState,notifyCancel=!!active&&!active.choosing&&!active.completed&&typeof active.onCancel==="function";
  pickerReturn=null;
  return closeModal(sheet).then(result=>{if(notifyCancel)active.onCancel();return result})}

async function confirmPickerSelection(){
  if(!pickerState||pickerState.mode!=="multi"||pickerState.choosing)return;
  const active=pickerState,handler=active.onPick;
  const picked=[...active.selected].map(pickerEntry).filter(Boolean);
  active.choosing=true;
  active.completed=true;
  try{if(handler)await handler(picked);await closeExercisePicker()}
  finally{if(pickerState===active)active.choosing=false}}

function pickerResumeOptions(){
  if(!pickerState)return null;
  return Object.assign({},pickerState.reopen,{query:pickerState.query,muscle:pickerState.muscle,
    equipment:pickerState.equipment,tab:pickerState.tab,selected:[...pickerState.selected]})}

// @ci-domain library,program,entry,workout
/* ---- custom exercise editor ---- */

/* Reachable editing, which the definition needs to be manageable at all: the
   sheet always supported an existing entry, but nothing ever passed one. */
function editCustomExercise(id){
  const entry=customExercises().find(e=>e.id===id);
  if(!entry)return;
  const reopen=libraryResumeOptions();
  openCustomExerciseSheet({entry,handoff:!!libFlow,
    onCancel:()=>{if(reopen)openLibrary(reopen)},
    onSave:()=>{if(reopen)openLibrary(reopen);else if(pickerState)renderPickerList()}})}

function renderCustomChips(){
  if(!customState)return;
  const chip=(val,label,active)=>
    `<button type="button" class="pchip${active?" is-active":""}" data-val="${esc(val)}" aria-pressed="${active?"true":"false"}">${esc(label)}</button>`;
  const eq=$("#exCustomEquip");
  if(eq){
    eq.innerHTML=PICKER_EQUIPMENT.map(x=>chip(x,t("picker.equipment."+x),customState.equipment.has(x))).join("");
    $$("#exCustomEquip .pchip").forEach(b=>b.onclick=()=>{
      const v=b.dataset.val;
      customState.equipment.has(v)?customState.equipment.delete(v):customState.equipment.add(v);
      renderCustomChips()})}
  for(const [sel,key] of [["#exCustomPrimary","primary"],["#exCustomSecondary","secondary"]]){
    const box=$(sel);if(!box)continue;
    box.innerHTML=MUSCLE_TOKENS.map(m=>chip(m,muscleLabel(m),customState[key].has(m))).join("");
    $$(`${sel} .pchip`).forEach(b=>b.onclick=()=>{
      const v=b.dataset.val;
      if(customState[key].has(v))customState[key].delete(v);
      else{customState[key].add(v);
        // A muscle cannot be both; picking a side moves it.
        customState[key==="primary"?"secondary":"primary"].delete(v)}
      renderCustomChips()})}}

function setCustomExercisePhase(active,phase){
  if(customState!==active)return false;
  const wasBusy=["saving","deleting","archiving","recovering","canceling"].includes(active.phase);
  const busy=["saving","deleting","archiving","recovering","canceling"].includes(phase);
  const sheet=$("#exCustomSheet");
  if(!wasBusy&&busy&&sheet?.contains(document.activeElement))active.busyFocus=document.activeElement;
  active.phase=phase;
  if(sheet)sheet.dataset.phase=phase;
  if(busy)sheet?.setAttribute("aria-busy","true");
  else sheet?.removeAttribute("aria-busy");
  const form=$("#exCustomSheet .custom__form");if(form)form.inert=busy;
  const save=$("#exCustomSave");
  if(save){const key=phase==="saving"?"custom.saving":phase==="canceling"?"custom.closing":
    phase==="recovering"?active.mutationOperation==="archive"?"custom.finishing_archive":
      active.mutationOperation==="delete"?"custom.finishing_delete":"custom.finishing_save":"dialog.save";
    save.dataset.i18n=key;save.textContent=t(key)}
  for(const selector of ["#exCustomSave","#exCustomCancel","#exCustomDelete"]){
    const button=$(selector);if(button)button.disabled=busy}
  const del=$("#exCustomDelete");
  if(del&&active.deleteAction){
    const pending=phase==="deleting"||phase==="archiving"||phase==="recovering";
    const key=pending&&active.mutationOperation==="archive"?"custom.archiving":
      pending&&active.mutationOperation==="delete"?"custom.deleting":active.deleteAction;
    del.dataset.i18n=key;del.textContent=t(key)}
  const recovery=$("#exCustomRecovery"),status=$("#exCustomRecoveryStatus");
  const recovering=phase==="recovering";
  if(recovery)recovery.hidden=!recovering;
  if(status){status.textContent=recovering?t(active.recoveryStatusKey||"custom.finishing_save"):"";
    status.setAttribute("aria-live","polite")}
  const retry=$("#exCustomRecoveryRetry");
  if(retry){retry.hidden=!recovering||!active.recoveryNeedsAction;
    retry.disabled=!active.recoveryNeedsAction||active.recoveryAttempt}
  const reload=$("#exCustomRecoveryReload");if(reload)reload.hidden=!recovering||!active.recoveryNeedsAction;
  if(!busy&&phase==="editing"&&wasBusy&&active.busyFocus?.isConnected){
    try{active.busyFocus.focus({preventScroll:true})}catch{try{active.busyFocus.focus()}catch{}}
    active.busyFocus=null}
  return true}

/* stageOnly builds a definition without writing it. Import review consumes the
   raw entry; Share repair consumes the explicit provenance handoff below, but
   neither flow writes durable state before its final commit. */
function openCustomExerciseSheet({entry=null,onSave=null,onCancel=null,handoff=false,stageOnly=false,repairHandoff=false}={}){
  const sheet=$("#exCustomSheet"),scrim=$("#exCustomScrim"),name=$("#exCustomName");
  if(!sheet)return;
  const inUse=entry?customExerciseInUse(entry.id):false;
  customState={id:entry?.id||null,sourceEntry:entry?cloneSnapshot(entry):null,onSave,stageOnly,repairHandoff,
    phase:"editing",duplicateAcknowledgedId:null,mutationId:null,mutationOperation:null,
    pendingMutation:null,recoveryAttempt:false,recoveryNeedsAction:false,recoveryStatusKey:null,busyFocus:null,
    deleteAction:entry?(inUse?"custom.archive":"custom.delete"):null,
    deleteOperation:entry?(inUse?"archive":"delete"):null,
    // Empty for a new definition: defaulting every custom exercise to Machine
    // quietly mislabels dumbbell and cable work the wizard then filters on.
    equipment:new Set(entry?.equipment||[]),
    primary:new Set(String(entry?.primary||"").split(",").filter(Boolean)),
    secondary:new Set(String(entry?.secondary||"").split(",").filter(Boolean))};
  setCustomExercisePhase(customState,"editing");
  customReturn=document.activeElement;
  if(name)name.value=entry?.name||"";
  setCustomNameError(null);
  const notes=$("#exCustomNotes");if(notes)notes.value=entry?.notes||"";
  const del=$("#exCustomDelete");
  if(del){const action=inUse?"custom.archive":"custom.delete";
    del.classList.toggle("hidden",!entry);del.dataset.i18n=action;del.textContent=t(action)}
  const used=$("#exCustomInUse");
  if(used)used.classList.toggle("hidden",!(entry&&inUse));
  customState.onCancel=onCancel;
  renderCustomChips();
  document.body.classList.add("is-sheet-open");
  // handoff lets this open over the picker: openModal stands the picker down
  // rather than refusing a second modal.
  openModal(sheet,{initialFocus:name,returnFocus:customReturn,onEscape:cancelCustomExerciseSheet,scrim,
    handoff,delayHide:reducedMotion()?0:280});
  requestAnimationFrame(()=>{sheet.classList.add("is-open");scrim?.classList.add("is-open")})}

function closeCustomExerciseSheet(){
  const sheet=$("#exCustomSheet");
  if(!sheet)return Promise.resolve(false);
  if(sheet.hidden&&!(activeModal&&activeModal.el===sheet))return Promise.resolve(false);
  customReturn=null;
  return closeModal(sheet)}
/* Backing out of the custom form returns to the picker it came from, with the
   search and any multi-selection intact. Dropping the lifter back to the
   program instead would throw away a browse they never finished. */
async function cancelCustomExerciseSheet(){
  const active=customState;
  if(!active||active.phase!=="editing")return;
  const back=active.onCancel;
  setCustomExercisePhase(active,"canceling");
  await closeCustomExerciseSheet();
  if(customState!==active)return;
  setCustomExercisePhase(active,"finished");
  if(back)await back()}

function customExerciseMutationSucceeded(result){
  return result?.committed===true&&result?.settled===true}
function customExerciseMutationNeedsRecovery(result){
  return result?.status==="partial"||result?.status==="deferred"||
    result?.recoveryPending===true||result?.finalizationPending===true||
    result?.pendingJournalCleanup===true}
function customExerciseMutationMatches(snapshot,mutation){
  const current=customExercises(snapshot).find(value=>value.id===mutation.id)||null;
  if(mutation.operation==="delete")return current===null&&!customExerciseInUse(mutation.id,snapshot);
  if(!current)return false;
  if(mutation.operation==="archive"){
    if(current.archived!==true)return false;
    const expected=cloneSnapshot(mutation.entry),actual=cloneSnapshot(current);
    delete expected.archived;delete actual.archived;
    return customExerciseStateEqual(actual,expected)}
  return customExerciseStateEqual(current,mutation.entry)}
function resolveCustomMutationIntent({head,journal}){
  const intent=journal?.customMutationIntent;
  if(intent?.version!==1||intent.operation!=="delete"||!isCustomLibraryId(intent.id)||
    intent.entry?.id!==intent.id)return{ok:false,code:"custom_mutation_intent_invalid"};
  const id=intent.id,source=normalizeCustomExercises([intent.entry])[0];
  if(!source||source.id!==id)return{ok:false,code:"custom_mutation_intent_invalid"};
  const current=customExercises(head).find(value=>value.id===id)||null;
  const referenced=customExerciseInUse(id,head);
  let snapshot=cloneSnapshot(head),mode="delete";
  if(referenced){
    mode="preserve-used";
    if(!current)snapshot=customExerciseUpsert(snapshot,source);
  }else if(current&&!customExerciseStateEqual(current,source)){
    // A concurrent edit owns the newer definition. The older Delete intent
    // must not erase it, even when the ID has not gained a reference.
    mode="preserve-changed";
  }else if(current){
    snapshot=customExerciseRemoveOrArchive(snapshot,id,"delete");
  }
  const expected=current&&!referenced&&!customExerciseStateEqual(current,source)
    ?cloneSnapshot(current):null;
  return{ok:true,snapshot,
    code:mode==="preserve-used"?"custom_delete_became_used":
      mode==="preserve-changed"?"custom_delete_changed_elsewhere":null,
    verify:value=>{
      const actual=customExercises(value).find(entry=>entry.id===id)||null;
      if(mode==="preserve-used")return actual
        ?{ok:true}:{ok:false,code:"custom_delete_definition_missing"};
      if(mode==="preserve-changed")return customExerciseStateEqual(actual,expected)
        ?{ok:true}:{ok:false,code:"custom_delete_newer_definition_changed"};
      return!actual&&!customExerciseInUse(id,value)
        ?{ok:true}:{ok:false,code:"custom_delete_not_safe"};
    }}
}
function customExerciseDeleteRecovery({snapshot,journal,mutation,stage}){
  if(mutation.operation!=="delete")return null;
  const marker=journal?.customMutationRecovery;
  if(stage==="journal")
    return marker?.operation==="delete"&&marker.id===mutation.id?{owned:true}:null;
  const referenced=customExerciseInUse(mutation.id,snapshot);
  const current=customExercises(snapshot).find(value=>value.id===mutation.id)||null;
  if(!referenced&&!current&&marker?.id!==mutation.id)return null;
  const entry=current||normalizeCustomExercises([mutation.entry])[0];
  if(!entry||entry.id!==mutation.id)return null;
  const candidate=current?snapshot:customExerciseUpsert(snapshot,entry);
  return{
    snapshot:candidate,
    code:referenced?"custom_delete_became_used":"custom_delete_changed_elsewhere",
    journalMarker:{version:1,operation:"delete",id:mutation.id},
    verify:value=>({ok:customExercises(value).some(item=>item.id===mutation.id)})
  }}
function returnCustomDeleteToEditing(active,mutation,snapshot,code){
  const entry=customExercises(snapshot).find(value=>value.id===mutation.id);
  if(!entry)return false;
  const inUse=customExerciseInUse(mutation.id,snapshot);
  active.sourceEntry=cloneSnapshot(entry);
  active.equipment=new Set(entry.equipment||[]);
  active.primary=new Set(String(entry.primary||"").split(",").filter(Boolean));
  active.secondary=new Set(String(entry.secondary||"").split(",").filter(Boolean));
  active.deleteAction=inUse?"custom.archive":"custom.delete";
  active.deleteOperation=inUse?"archive":"delete";
  active.mutationOperation=null;
  active.mutationId=null;
  active.pendingMutation=null;
  active.recoveryAttempt=false;
  active.recoveryNeedsAction=false;
  active.recoveryStatusKey=null;
  const name=$("#exCustomName");if(name)name.value=entry.name||"";
  const notes=$("#exCustomNotes");if(notes)notes.value=entry.notes||"";
  renderCustomChips();
  $("#exCustomInUse")?.classList.toggle("hidden",!inUse);
  setCustomExercisePhase(active,"editing");
  if(inUse)toast(t("toast.custom_became_used"));
  else if(code==="custom_delete_changed_elsewhere")toast(t("toast.custom_changed"));
  return true}
async function recoverCustomExerciseMutation(active,mutation){
  if(customState!==active)return false;
  active.pendingMutation=mutation;
  active.recoveryAttempt=true;active.recoveryNeedsAction=false;
  active.recoveryStatusKey=mutation.operation==="archive"?"custom.finishing_archive":
    mutation.operation==="delete"?"custom.finishing_delete":"custom.finishing_save";
  setCustomExercisePhase(active,"recovering");
  let receipt=null;
  try{receipt=await DurableState.settleCustomExerciseMutation({
    pendingJournalId:mutation.pendingJournalId,
    verify:({snapshot})=>customExerciseMutationMatches(snapshot,mutation)
      ?{ok:true}
      :{ok:false,code:mutation.operation==="delete"&&customExerciseInUse(mutation.id,snapshot)
        ?"custom_delete_became_used":"custom_settlement_mismatch"},
    recover:context=>customExerciseDeleteRecovery({...context,mutation})
  })}catch{}
  if(customState!==active)return false;
  if(typeof receipt?.pendingJournalId==="string")mutation.pendingJournalId=receipt.pendingJournalId;
  if(customExerciseMutationSucceeded(receipt))return true;
  if(receipt?.semanticRecovery===true&&
    (receipt.code==="custom_delete_became_used"||receipt.code==="custom_delete_changed_elsewhere")&&
    returnCustomDeleteToEditing(active,mutation,receipt.head,receipt.code))return false;
  active.recoveryAttempt=false;active.recoveryNeedsAction=true;
  active.recoveryStatusKey="custom.recovery.unresolved";
  setCustomExercisePhase(active,"recovering");
  $("#exCustomRecoveryRetry")?.focus();
  return false}
async function retryCustomExerciseRecovery(){
  const active=customState;
  if(!active||active.phase!=="recovering"||active.recoveryAttempt||!active.pendingMutation)return;
  const mutation=active.pendingMutation;
  const settled=await recoverCustomExerciseMutation(active,mutation);
  if(settled)await finishCustomExerciseMutation(active,{operation:mutation.operation,entry:mutation.entry})}
async function finishCustomExerciseMutation(active,{operation,entry}){
  await closeCustomExerciseSheet();
  if(customState!==active)return;
  setCustomExercisePhase(active,"finished");
  const message=operation==="create"?"toast.custom_created":
    operation==="edit"?"toast.custom_saved":
    operation==="archive"?"toast.custom_archived":"toast.custom_deleted";
  toast(t(message));
  if(operation==="create")customCreatedToastAt=performance.now();
  if(operation==="delete"||operation==="archive"){
    if(libFlow)renderLibrary();else if(pickerState)renderPickerList();
    return}
  if(active.onSave&&entry)await active.onSave(entry);
  else if(pickerState)renderPickerList()}

/** The name field carries its own error (R7 J-21): focus, aria-invalid and a note linked by aria-describedby, not a toast alone. */
const CUSTOM_NAME_ERROR_ID="exCustomNameError";
function setCustomNameError(message){
  const input=$("#exCustomName");if(!input)return;
  let note=document.getElementById(CUSTOM_NAME_ERROR_ID);
  if(!message){
    input.removeAttribute("aria-invalid");
    if(input.getAttribute("aria-describedby")===CUSTOM_NAME_ERROR_ID)input.removeAttribute("aria-describedby");
    note?.remove();return}
  if(!note){
    note=document.createElement("p");note.id=CUSTOM_NAME_ERROR_ID;note.className="custom__error";note.setAttribute("role","alert");
    (input.closest("label")||input).after(note)}
  note.textContent=message;
  input.setAttribute("aria-invalid","true");input.setAttribute("aria-describedby",CUSTOM_NAME_ERROR_ID);
  try{input.focus()}catch{}}
async function saveCustomExerciseSheet(){
  const active=customState;
  if(!active||active.phase!=="editing")return;
  const name=String($("#exCustomName")?.value||"").trim();
  if(!name){setCustomNameError(t("toast.custom_needs_name"));return}
  if(!active.id){
    const twin=pickableExercises().find(e=>foldSearch(libraryName(e))===foldSearch(name)||foldSearch(e.name)===foldSearch(name));
    if(twin&&twin.id!==active.duplicateAcknowledgedId){
      // Offer what already exists before minting a near-identical second copy.
  if(confirm(t("confirm.custom_duplicate",{name:libraryName(twin)}))){
        const handler=active.onSave;
        setCustomExercisePhase(active,"saving");
        await closeCustomExerciseSheet();
        if(customState!==active)return;
        if(handler)await handler(active.repairHandoff
          ? {entry:twin,stagedCustomDefinition:null}
          : twin);
        setCustomExercisePhase(active,"finished");
        return}
      active.duplicateAcknowledgedId=twin.id}}
  // Equipment and a primary muscle are what make the definition usable: the
  // wizard filters on one and the volume audit groups by the other. Exact
  // duplicates above reuse their trusted definition instead of requiring the
  // custom form to restate those facts.
  if(!active.equipment.size){toast(t("toast.custom_needs_equipment"));return}
  if(!active.primary.size){toast(t("toast.custom_needs_primary"));return}
  const editing=!!active.id;
  const operation=editing?"edit":"create";
  const handler=active.onSave;
  if(!active.mutationId)active.mutationId=active.id||`${CUSTOM_ID_PREFIX}${uid()}`;
  active.mutationOperation=operation;
  setCustomExercisePhase(active,"saving");
  if(active.stageOnly){
    const staged=normalizeCustomExercises([{id:active.id||`${CUSTOM_ID_PREFIX}${uid()}`,name,
      equipment:[...active.equipment],
      primary:[...active.primary].join(","),
      secondary:[...active.secondary].join(","),
      notes:String($("#exCustomNotes")?.value||"").trim()}])[0];
    await closeCustomExerciseSheet();
    if(customState!==active)return;
    if(handler&&staged){
      const choice=active.repairHandoff
        ? {entry:active.id?active.sourceEntry||staged:staged,
          stagedCustomDefinition:active.id?null:staged}
        : staged;
      await handler(choice);
    }
    setCustomExercisePhase(active,"finished");
    return}
  let saved;
  try{saved=await saveCustomExercise({id:active.mutationId,name,
    equipment:[...active.equipment],
    primary:[...active.primary].join(","),
    secondary:[...active.secondary].join(","),
    notes:String($("#exCustomNotes")?.value||"").trim()},storageIO,
    {expectedEntry:editing?active.sourceEntry:null})}
  catch{setCustomExercisePhase(active,"editing");toast(t("toast.custom_save_failed"));return}
  if(customState!==active)return;
  const {result,entry}=saved;
  if(customExerciseMutationSucceeded(result)){
    await finishCustomExerciseMutation(active,{operation,entry});return}
  if(customExerciseMutationNeedsRecovery(result)){
    const settled=await recoverCustomExerciseMutation(active,{operation,id:active.mutationId,entry,
      pendingJournalId:result.pendingJournalId||null});
    if(settled)await finishCustomExerciseMutation(active,{operation,entry});
    return}
  setCustomExercisePhase(active,"editing");
  toast(t(result?.code==="custom-exercise-changed"?"toast.custom_changed":"toast.custom_save_failed"))}

async function deleteCustomExerciseSheet(){
  const active=customState;
  if(!active?.id||active.phase!=="editing")return;
  const operation=active.deleteOperation||"delete";
  active.mutationOperation=operation;
  setCustomExercisePhase(active,operation==="archive"?"archiving":"deleting");
  let result;
  try{result=await deleteCustomExercise(active.id,storageIO,
    {action:operation,expectedEntry:active.sourceEntry})}
  catch{setCustomExercisePhase(active,"editing");toast(t("toast.custom_save_failed"));return}
  if(customState!==active)return;
  if(!result){setCustomExercisePhase(active,"editing");toast(t("toast.custom_in_use"));return}
  if(customExerciseMutationSucceeded(result)){
    await finishCustomExerciseMutation(active,{operation,entry:active.sourceEntry});
    return}
  if(customExerciseMutationNeedsRecovery(result)){
    const settled=await recoverCustomExerciseMutation(active,{operation,id:active.id,
      entry:active.sourceEntry,pendingJournalId:result.pendingJournalId||null});
    if(settled)await finishCustomExerciseMutation(active,{operation,entry:active.sourceEntry});
    return}
  setCustomExercisePhase(active,"editing");
  if(result.code==="custom-exercise-became-used"){
    active.deleteOperation="archive";active.deleteAction="custom.archive";
    active.mutationOperation=null;
    const deleteButton=$("#exCustomDelete");
    if(deleteButton){deleteButton.dataset.i18n=active.deleteAction;deleteButton.textContent=t(active.deleteAction)}
    $("#exCustomInUse")?.classList.remove("hidden");
    toast(t("toast.custom_became_used"));return}
  toast(t(result?.code==="custom-exercise-changed"?"toast.custom_changed":"toast.custom_save_failed"))}

/** Clipboard first; the hidden-textarea path covers browsers that refuse the
 *  async clipboard, and only a genuine failure of both surfaces a toast. */
// @ci-domain global
async function copyToClipboard(text,okKey,failKey){
  try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);
    toast(t(okKey));return true}}catch{}
  try{const ta=document.createElement("textarea");
    ta.value=text;ta.setAttribute("readonly","");
    ta.style.cssText="position:fixed;top:0;left:0;opacity:0";
    document.body.append(ta);ta.select();
    const ok=document.execCommand("copy");ta.remove();
    if(ok){toast(t(okKey));return true}}catch{}
  toast(t(failKey));return false}
async function copyProgramText(){
  return copyToClipboard($("#programTextOut")?.textContent||programText(),
    "toast.program_text_copied","toast.program_text_copy_failed")}
function shareProgramText(){
  return shareOrDownload($("#programTextOut")?.textContent||programText(),programTextName(),"text/plain")}
/* An imported split arrives as names. Matching them to the library is what
   turns it from a list of strings into something the app can reason about:
   muscle tags for the volume audit, and a link the swap picker can work from.
   Names that find no match keep exactly what was imported — the program is the
   lifter's, not the library's — and their slots show an accented swap button
   in the editor so linking them by hand is one tap. */
function linkImportedExercises(list){
  const byName=new Map();
  for(const entry of pickableExercises()){
    for(const n of [entry.name,entry.namePt]){
      const key=foldSearch(n);
      if(key&&!byName.has(key))byName.set(key,entry)}}
  let linked=0;
  for(const ex of list){
    if(!ex||typeof ex!=="object")continue;
    // A Taurifer export already carries links; only repoint ids the library
    // has since merged, and never overwrite a link that still resolves.
    if(ex.libraryId){
      const known=libraryEntry(ex.libraryId);
      if(known){ex.libraryId=known.id;linked++;continue}
      delete ex.libraryId}
    const match=byName.get(foldSearch(ex.name));
    if(!match)continue;
    ex.libraryId=match.id;
    if(!String(ex.primary??"").trim())ex.primary=match.primary||"";
    if(!String(ex.secondary??"").trim())ex.secondary=match.secondary||"";
    if(!String(ex.notes??"").trim()&&match.notes)ex.notes=match.notes;
    linked++}
  return{linked,total:list.length}}

/* ============================================================
   Program import — staged, reviewed, then written
   Parsing produces a transient model only. Nothing durable moves
   until the lifter presses Import, so a file that turns out to be
   wrong costs them nothing. Names are classified rather than
   guessed at: an exact hit links itself, a likely one has to be
   looked at, and anything else keeps exactly what was imported.
   ============================================================ */

const IMPORT_EXACT="exact",IMPORT_ALIAS="alias",IMPORT_PROBABLE="probable",IMPORT_UNMATCHED="unmatched";
let importDraft=null,importReturn=null;

/* Taurifer's own text export, read back. The grammar is the one programText()
   writes: a title line, then "DAY NAME: muscles", then "1. Exercise: 3× 6 to 10".
   Anything that does not look like that is rejected rather than guessed at —
   this parses one known format, it does not read prose. */
/* The text export shouts day names ("DAY 1", "TREINO A") for legibility, so a
   round-trip would otherwise bring the shouting back into the program. A label
   with no lowercase at all was uppercased on the way out; anything else is left
   exactly as written. */
function restoreExportCase(label){
  if(label!==label.toLocaleUpperCase(locTag())||!/[a-z]/i.test(label))return label;
  return label.toLocaleLowerCase(locTag()).replace(/(^|\s)(\p{L})/gu,(m,sp,ch)=>sp+ch.toLocaleUpperCase(locTag()))}
function stripProgramTextTitleMeta(label){
  return String(label||"").replace(/\s*(?:\(\s*|,\s*)\d+\s*(?:days?\s*\/\s*week|days?\s+per\s+week|dias?\s*\/\s*semana|dias?\s+por\s+semana)\s*\)?\s*$/iu,"").trim()}
function parseProgramTextExport(text){
  const lines=String(text||"").split(/\r?\n/);
  const dataIndex=lines.findIndex(line=>line.trim()===PROGRAM_TEXT_DATA_MARKER);
  let data=null;
  if(dataIndex>=0){try{const parsed=JSON.parse(lines[dataIndex+1]||"");if(parsed&&parsed.version===1)data=parsed}catch{}}
  const content=dataIndex<0?lines:lines.filter((_,index)=>index!==dataIndex&&index!==dataIndex+1);
  const days=[];let current=null,title="";
  const exRe=/^\s*(\d+)\.\s*(.+?)(?:\s*[—-]\s*|\s*:\s*)(\d+)\s*[×x]\s*(\d+)(?:\s*(?:[–-]|to|a)\s*(\d+))?\s*$/iu;
  for(const raw of content){
    const line=raw.trim();
    if(!line)continue;
    const ex=line.match(exRe);
    if(ex){
      if(!current){current={day:`Day ${days.length+1}`,rows:[]};days.push(current)}
      const min=+ex[4],max=ex[5]?+ex[5]:min;
      const legacy=ex[2].trim().match(/^(.*)\s+\[(range|manual|rep_goal|anchor_backoff)@(\d+)\]$/iu);
      const row={name:(legacy?.[1]||ex[2]).trim(),sets:+ex[3],min,max};
      // Read the pre-appendix range marker without exposing it in the new
      // export. Its parameters are the already-authored text targets; other
      // strategy markers remain structural and cannot invent executable data.
      if(legacy?.[2].toLowerCase()==="range"&&legacy[3]==="1")row.progression={
        schemaVersion:1,strategy:{id:"range",version:1,params:{workingSets:row.sets,repMin:row.min,repMax:row.max}},modifiers:[]};
      current.rows.push(row);
      continue}
    // A non-exercise line starts a day, except the first which is the title.
    if(!title&&!days.length){title=restoreExportCase(stripProgramTextTitleMeta(line));continue}
    const label=line.split(/\s*[—-]\s+|\s*:\s+/)[0].trim();
    if(!label)continue;
    current={day:restoreExportCase(label),rows:[]};days.push(current)}
  const exercises=[];
  for(const d of days)
    d.rows.forEach((r,i)=>{
      const carried=data?.exercises?.find(ex=>ex?.day===d.day&&ex?.order===i+1);
      exercises.push({day:d.day,order:i+1,name:r.name,sets:r.sets,min:r.min,max:r.max,
        ...(carried?.id?{id:carried.id}:{ }),...(carried?.movementId?{movementId:carried.movementId}:{ }),
        ...(carried?.progression?{progression:carried.progression}:r.progression?{progression:r.progression}:{}),
        ...(carried?.progressionIncompatibility?{progressionIncompatibility:carried.progressionIncompatibility}:{} )});
    });
  if(!exercises.length)return null;
  const metaOut=title?{name:title}:null;
  if(metaOut&&data){if(Array.isArray(data.relations))metaOut.progressionRelations=data.relations;if(Array.isArray(data.modifiers))metaOut.progressionModifiers=data.modifiers;if(Array.isArray(data.incompatibilities))metaOut.progressionIncompatibilities=data.incompatibilities}
  return{exercises,meta:metaOut,customExercises:[]}}

const IMPORT_MAX_BYTES=1024*1024;
const IMPORT_MAX_DEPTH=32;
// A canonical 12-cycle program file has tens of thousands of nodes; this
// matches the setup-draft bound that program must already fit.
const IMPORT_MAX_NODES=65536;
function importUtf8Bytes(value){return new TextEncoder().encode(String(value||"")).byteLength}
// A backup carries every archived block's full ProgramDefinition (a generated
// program is roughly 300 KB and 25,000 nodes), so whole-state files get their
// own bound instead of the program-file one.
const BACKUP_MAX_BYTES=16*1024*1024;
const BACKUP_MAX_NODES=2000000;
function boundedImportJson(text,{maxBytes=IMPORT_MAX_BYTES,maxNodes=IMPORT_MAX_NODES}={}){
  if(importUtf8Bytes(text)>maxBytes)return null;
  let parsed;
  try{parsed=JSON.parse(String(text||""))}catch{return null}
  let nodes=0;
  const visit=(value,depth)=>{
    if(++nodes>maxNodes||depth>IMPORT_MAX_DEPTH)return false;
    if(value===null||typeof value!=="object")return true;
    if(Array.isArray(value))return value.every(child=>visit(child,depth+1));
    return Object.keys(value).every(key=>visit(value[key],depth+1))};
  return visit(parsed,0)?parsed:null}
function importedMuscleValues(row,{canonical=false}={}){
  for(const key of ["primary","secondary"]){
    if(!Object.prototype.hasOwnProperty.call(row,key))continue;
    const result=MuscleDomain.normalizeMuscleAttribution(row[key]);
    if(!result.ok||canonical&&result.value!==row[key])return false;
  }
  return true}
function validImportedExerciseRow(row){
  if(!row||typeof row!=="object"||Array.isArray(row))return false;
  const text=v=>typeof v==="string"&&v.trim().length>0;
  return text(row.day)&&Number.isInteger(row.order)&&row.order>=1&&row.order<=1000&&
    text(row.name)&&Number.isInteger(row.sets)&&row.sets>=1&&row.sets<=100&&
    Number.isInteger(row.min)&&row.min>=1&&row.min<=1000&&
    Number.isInteger(row.max)&&row.max>=row.min&&row.max<=1000&&
    (row.libraryId===undefined||text(row.libraryId))&&importedMuscleValues(row,{canonical:true});}
function validRawImportedExerciseRow(row){
  if(!row||typeof row!=="object"||Array.isArray(row))return false;
  const text=v=>typeof v==="string"&&v.trim().length>0;
  // A legacy alias is accepted only when it is itself well-formed. Do not let
  // a valid repLow/repHigh silently mask a malformed canonical min/max field.
  if(Object.prototype.hasOwnProperty.call(row,"min")&&
    (!Number.isInteger(row.min)||row.min<1||row.min>1000))return false;
  if(Object.prototype.hasOwnProperty.call(row,"max")&&
    (!Number.isInteger(row.max)||row.max<1||row.max>1000))return false;
  if(Object.prototype.hasOwnProperty.call(row,"repLow")&&
    (!Number.isInteger(row.repLow)||row.repLow<1||row.repLow>1000))return false;
  if(Object.prototype.hasOwnProperty.call(row,"repHigh")&&
    (!Number.isInteger(row.repHigh)||row.repHigh<1||row.repHigh>1000))return false;
  const min=Number.isInteger(row.min)?row.min:row.repLow;
  const max=Number.isInteger(row.max)?row.max:row.repHigh;
  return text(row.day)&&text(row.name)&&Number.isInteger(row.sets)&&row.sets>=1&&row.sets<=100&&
    Number.isInteger(min)&&min>=1&&min<=1000&&Number.isInteger(max)&&max>=min&&max<=1000&&
    (row.order===undefined||(Number.isInteger(row.order)&&row.order>=1&&row.order<=1000))&&
    (row.libraryId===undefined||text(row.libraryId))&&importedMuscleValues(row);}
function normalizeImportedRows(rows){
  const orders=new Map();
  return rows.map(row=>{
    const out={...row};
    // Older program-only exports carried repLow/repHigh and omitted order.
    // These are lossless aliases: order is the row's position within its day,
    // and bounds are copied only when the source supplied valid integers.
    if(out.order===undefined&&typeof out.day==="string"){
      const next=(orders.get(out.day)||0)+1;orders.set(out.day,next);out.order=next}
    if(out.min===undefined&&Number.isInteger(out.repLow))out.min=out.repLow;
    if(out.max===undefined&&Number.isInteger(out.repHigh))out.max=out.repHigh;
    for(const key of ["primary","secondary"]){
      if(!Object.prototype.hasOwnProperty.call(out,key))continue;
      out[key]=MuscleDomain.normalizeMuscleAttribution(out[key]).value}
    return out})}
const PROGRAM_FILE_KIND="taurifer-program",PROGRAM_FILE_VERSION=4;
/* A Taurifer program file is imported as its exact definition: every row is
   already a catalog or carried custom identity, so nothing is matched by name. */
function parseCanonicalProgramFile(parsed){
  if(parsed.version!==PROGRAM_FILE_VERSION)return null;
  const customs=Array.isArray(parsed.customExercises)?parsed.customExercises:[];
  if(!customs.every(validImportedCustomExercise))return null;
  const normalizedCustoms=normalizeCustomExercises(customs);
  const definition=canonicalProgramDefinition(parsed.definition,normalizedCustoms);
  if(!definition)return null;
  return{format:"json",legacy:false,exercises:flatProgramFromDefinition(definition,normalizedCustoms,1),
    customExercises:normalizedCustoms,meta:{name:String(parsed.name||"").slice(0,80)},definition}}
function parseProgramSource(text,fileName=""){
  const trimmed=String(text||"").trim();
  if(trimmed.startsWith("{")||trimmed.startsWith("[")){
    const parsed=boundedImportJson(trimmed);if(parsed===null)return null;
    if(parsed?.kind===PROGRAM_FILE_KIND)return parseCanonicalProgramFile(parsed);
    const imp=parseProgramImport(parsed);
    if(!imp?.exercises?.length||!imp.exercises.every(validRawImportedExerciseRow)||
      !imp.customExercises.every(validImportedCustomExercise))return null;
    imp.exercises=normalizeImportedRows(imp.exercises);
    if(!imp.exercises.every(validImportedExerciseRow))return null;
    return Object.assign({format:"json",legacy:parsed?.version===undefined},imp)}
  if(importUtf8Bytes(trimmed)>IMPORT_MAX_BYTES)return null;
  const text2=parseProgramTextExport(trimmed);
  return text2?Object.assign({format:"text"},text2):null}

/* Words that survive the length filter but carry no movement signal. The
   Portuguese "com" is the expensive one: it made every barbell movement share a
   token with "Hip thrust com barra", so thirty-six entries tied at 0.50 and
   array order picked the winner. */
const MATCH_STOPWORDS=new Set([
  "com","sem","para","por","dos","das","nos","nas","que","seu","sua","pes",
  "the","and","for","with","your","from","into"]);
/* Equipment still informs a match; it must never decide one alone. Scored at a
   fraction of a movement token, then used to break ties, where it is the
   difference between "Hip thrust na maquina" reaching the machine or the bar. */
const MATCH_EQUIPMENT=new Set([
  "barra","halteres","haltere","maquina","polia","cabo","smith","banco",
  "cadeira","mesa","corda","anilha","barbell","dumbbell","machine","cable",
  "bar","bench","rope","plate"]);
const MATCH_EQUIPMENT_TOKENS={
  barbell:["barra","barbell"],dumbbell:["halteres","haltere","dumbbell"],
  machine:["maquina","machine"],cable:["cabo","polia","cable"],
  smith:["smith"],bodyweight:["corpo","bodyweight"]};
const MATCH_EQUIPMENT_WEIGHT=0.25;
const matchTokens=s=>foldSearch(s).split(/[^a-z0-9]+/)
  .filter(w=>w.length>2&&!MATCH_STOPWORDS.has(w));
const matchWeight=w=>MATCH_EQUIPMENT.has(w)?MATCH_EQUIPMENT_WEIGHT:1;
const matchWeightSum=list=>list.reduce((sum,w)=>sum+matchWeight(w),0);

/* How close two movement names are, 0..1, on shared words. Deliberately dumb:
   it only has to be good enough to say "look at this one", never to decide.
   Movement words carry the weight; stopwords carry none and equipment a
   quarter, so "com barra" can no longer outvote "hip thrust". */
function nameAffinity(a,b){
  const wa=matchTokens(a);
  const wb=new Set(matchTokens(b));
  if(!wa.length||!wb.size)return 0;
  const hits=matchWeightSum(wa.filter(w=>wb.has(w)));
  const denom=Math.max(matchWeightSum(wa),matchWeightSum([...wb]));
  return denom?hits/denom:0}

/* A library name wholly present inside the lifter's line. "Leg press 45°, pés
   altos e afastados" is the library's "Leg press" plus the lifter's own setup
   notes, and diluting the score by those notes discarded an exact reading. */
function nameContainment(input,libraryName){
  const wb=matchTokens(libraryName);
  if(!wb.length)return false;
  const wa=new Set(matchTokens(input));
  return wb.every(w=>wa.has(w))}

/* Whether the lifter's line names the equipment this entry uses. */
function matchEquipmentAgrees(input,entry){
  const list=Array.isArray(entry?.equipment)?entry.equipment:[];
  if(!list.length)return false;
  const wa=new Set(matchTokens(input));
  return list.some(kind=>(MATCH_EQUIPMENT_TOKENS[kind]||[kind]).some(tok=>wa.has(tok)))}

/* The floor is a display filter and never a trust gate: buildImportDraft gives
   probable and unmatched rows the same decision and the same unreviewed state,
   so lowering it cannot let anything through unseen. Below it a row proposes
   nothing rather than a guess it cannot stand behind. */
const IMPORT_PROBABLE_MIN=0.35;
const IMPORT_CANDIDATE_LIMIT=3;

/* Classifies one imported row against the library plus the definitions that
   travelled with the file. */
function classifyImportRow(row,candidates){
  const name=String(row.name??"").trim();
  if(row.libraryId){
    const known=candidates.find(e=>e.id===row.libraryId)||libraryEntry(row.libraryId);
    if(known)return{status:IMPORT_EXACT,match:known}}
  const folded=foldSearch(name);
  if(!folded)return{status:IMPORT_UNMATCHED,match:null};
  const exact=candidates.find(e=>foldSearch(e.name)===folded);
  if(exact)return{status:IMPORT_EXACT,match:exact};
  // The same movement written in the other language is a match, but one the
  // lifter should still see, since the name in their file will change.
  const alias=candidates.find(e=>foldSearch(e.namePt||"")===folded);
  if(alias)return{status:IMPORT_ALIAS,match:alias};
  // A curated alias went through the same editorial gate as the entry it points
  // at, so "RDL means Romanian deadlift" is settled rather than guessed, and the
  // row arrives confirmed like any other alias hit. Aliases add ways to reach a
  // movement; they never change which movement an id means.
  const curated=candidates.find(e=>(e.aliases||[]).some(a=>foldSearch(a)===folded));
  if(curated)return{status:IMPORT_ALIAS,match:curated};
  const ranked=rankImportCandidates(name,candidates);
  if(!ranked.length)return{status:IMPORT_UNMATCHED,match:null,candidates:[]};
  return{status:IMPORT_PROBABLE,match:ranked[0].entry,score:ranked[0].score,candidates:ranked}}

/* The ranked shortlist behind a review row. Scoring moves the right entry into
   this list; it does not reliably move it to the front, because a line like
   "Hack squat" never says whether the barbell or the machine is meant. So the
   row offers the list rather than a verdict.

   Order: a contained library name first, then weighted overlap, then the entry
   whose equipment the lifter actually named, then the library's own rank, and
   last the array position, so a tie never rests on position alone. */
function rankImportCandidates(name,candidates,limit=IMPORT_CANDIDATE_LIMIT){
  const scored=[];
  for(let i=0;i<candidates.length;i++){
    const e=candidates[i];
    const names=[e.name,e.namePt||"",...(e.aliases||[])];
    const score=names.reduce((best,n)=>Math.max(best,nameAffinity(name,n)),0);
    const contained=names.some(n=>nameContainment(name,n));
    if(!contained&&score<IMPORT_PROBABLE_MIN)continue;
    scored.push({entry:e,score,contained,equipment:matchEquipmentAgrees(name,e),
      rank:Number.isFinite(e.rank)?e.rank:50,order:i})}
  scored.sort((a,b)=>
    (b.contained?1:0)-(a.contained?1:0)||
    b.score-a.score||
    (b.equipment?1:0)-(a.equipment?1:0)||
    a.rank-b.rank||
    a.order-b.order);
  return scored.slice(0,limit)}

/* Builds the review model. Exact and alias hits arrive decided; a probable one
   arrives undecided and blocks Import until it is looked at. */
function buildImportDraft(source,fileName){
  const candidates=source.customExercises?.length
    ? normalizeCustomExercises(source.customExercises).concat(pickableExercises())
    : pickableExercises();
  const rows=source.exercises.map((raw,i)=>{
    const {status,match,candidates:ranked}=classifyImportRow(raw,candidates);
    return{key:`imp${i}`,raw:cloneSnapshot(raw),status,match,
      shortlist:(ranked||[]).map(c=>c.entry),
      decision:status===IMPORT_EXACT||status===IMPORT_ALIAS?"link":"raw",
      reviewed:status===IMPORT_EXACT||status===IMPORT_ALIAS}});
  return{fileName:String(fileName||""),format:source.format||"json",
    legacy:source.legacy===true,
    meta:source.meta||null,customExercises:source.customExercises||[],rows,
    ...(source.definition?{definition:cloneSnapshot(source.definition)}:{})}}

const importCounts=draft=>{
  const linked=draft.rows.filter(r=>r.decision==="link").length;
  const review=draft.rows.filter(r=>!r.reviewed).length;
  const custom=draft.rows.filter(r=>r.decision==="custom").length;
  return{linked,review,custom,total:draft.rows.length}};

/* Turns reviewed rows into program templates. A linked row takes the
   definition's identity; a raw row keeps precisely what the file said. */
function importDraftExercises(draft){
  return draft.rows.map(r=>{
    const base=cloneSnapshot(r.raw);
    delete base.libraryId;delete base.displayName;
    if(r.decision==="link"&&r.match)
      return Object.assign(base,exerciseFieldsFromLibrary(r.match));
    if(r.decision==="custom"&&r.createdCustomId)
      return Object.assign(base,{libraryId:r.createdCustomId});
    return base})}

/* Definitions that have to exist before the templates can resolve: the ones
   that travelled in a v3 file, plus any created during review. */
function importDraftCustomDefinitions(draft){
  const out=[];
  for(const e of normalizeCustomExercises(draft.customExercises))out.push(e);
  for(const r of draft.rows)if(r.createdCustom)out.push(r.createdCustom);
  return out}

// @ci-domain library,program
/* ============================================================
   The library flow
   One controller behind three surfaces: the quick-add sheet on a
   training day, the full browse page it opens into, and the
   configuration step that follows a multi-selection. The picker
   sheet keeps serving the single-pick jobs (change, substitute)
   — this is the "add to my program" path, where
   choosing several at once and setting their sets afterwards is
   what a lifter actually does.
   ============================================================ */

const LIB_TABS=["suggested","recent","yours"];
const LIB_PAGE_TABS=["search","browse","yours"];
let libFlow=null,libReturn=null,previewState=null;

/* What this day is short of. A day that already has two chest presses does not
   need a third suggested; one with no back work does. Ranked so the staple for
   an uncovered pattern leads. */
function suggestedForDay(dayName,limit=6){
  const onDay=programEditorProgram().forDay(dayName);
  const have=new Set(onDay.map(e=>e.libraryId).filter(Boolean));
  const covered=new Set();
  for(const e of onDay)for(const m of muscles(e.primary))covered.add(m);
  const scored=[];
  for(const e of EXERCISE_LIBRARY){
    if(have.has(e.id))continue;
    const prim=muscles(e.primary);
    const fresh=prim.some(m=>!covered.has(m));
    scored.push({e,score:(fresh?0:1)*100+(e.rank??50)})}
  scored.sort((a,b)=>a.score-b.score||libraryName(a.e).localeCompare(libraryName(b.e)));
  return scored.slice(0,limit).map(x=>x.e)}

/* Most recently trained first, so the movements a lifter keeps coming back to
   are the ones they see. Reads library ids, which survive a language change. */
function recentExercises(limit=8){
  const seen=[],ids=new Set();
  const log=[...(state.log||[])].sort((a,b)=>compareLogChronology(b,a));
  const add=id=>{if(!id||ids.has(id))return;const entry=libraryEntry(id);if(!entry)return;ids.add(id);seen.push(entry)};
  for(const r of log){
    if(seen.length>=limit)break;
    if(r.performedLibraryId)add(r.performedLibraryId)}
  for(const e of state.program||[]){if(seen.length>=limit)break;add(e.libraryId)}
  return seen.slice(0,limit)}

const yourExercises=()=>customExercises().filter(e=>!e.archived);

function libTabList(tab,{page=false}={}){
  if(tab==="yours")return yourExercises();
  if(tab==="recent")return recentExercises();
  if(tab==="suggested")return suggestedForDay(libFlow?.day||day);
  return pickableExercises()}

/* ---- quick add ---- */

function renderQuickTabs(){
  const el=$("#exPickTabs");if(!el||!pickerState?.quick)return;
  el.classList.remove("hidden");
  el.innerHTML=LIB_TABS.map(tab=>
    `<button type="button" role="tab" class="picktab${pickerState.tab===tab?" is-active":""}" `+
    `aria-selected="${pickerState.tab===tab?"true":"false"}" data-tab="${tab}">${esc(t("picker.tab."+tab))}</button>`).join("");
  $$("#exPickTabs .picktab").forEach(b=>b.onclick=()=>{pickerState.tab=b.dataset.tab;renderQuickTabs();renderPickerList()})}

/* ---- full library page ---- */

function librarySelectionMap(selected){const out=new Map();
  for(const item of Array.isArray(selected)?selected:[]){
    const pair=Array.isArray(item)?item:[item,null],id=String(pair[0]||"");if(!id)continue;
    out.set(id,pair[1]?cloneSnapshot(pair[1]):null)}
  return out}
function libraryResumeOptions(){
  if(!libFlow)return null;
  return{day:libFlow.day,tab:libFlow.tab,query:libFlow.query,muscle:libFlow.muscle,
    equipment:libFlow.equipment,step:libFlow.step,editorScope:libFlow.editorScope,
    selected:[...libFlow.selected.entries()].map(cloneSnapshot)}}
function openLibrary({day:dayName=day,selected=[],step="browse",tab="browse",query="",muscle=null,equipment=null,editorScope=false,returnTo=null}={}){
  libFlow={day:dayName,tab:LIB_PAGE_TABS.includes(tab)?tab:"browse",query:String(query||""),muscle,equipment,step,
    editorScope:!!editorScope,selected:librarySelectionMap(selected)};
  // Reached through the picker, the control that was pressed is the picker's own and it is gone by now: the caller
  // names the control that opened the picker instead (R7 J-19).
  libReturn=returnTo||document.activeElement;
  const settle=routePushBegin("in",{pushed:$("#library"),under:routeViewEl(currentViewId())});
  document.body.classList.add("is-library");
  document.body.classList.remove("is-preview");
  $$(".view").forEach(v=>v.classList.toggle("active",v.id==="library"));
  window.scrollTo({top:0});
  const search=$("#libSearch");if(search)search.value=libFlow.query;
  renderLibrary();
  search?.focus({preventScroll:true});
  settle?.()}

function closeLibrary({toProgram=true}={}){
  const returnToOnboarding=!!libFlow?.editorScope&&setupEditorOpen;
  libFlow=null;
  const settle=toProgram?routePushBegin("out",{pushed:$("#library"),under:routeViewEl(returnToOnboarding?"onboarding":"program")}):null;
  document.body.classList.remove("is-library","is-preview");
  let back=resolveReturnFocus(libReturn);
  // The editor may have redrawn its Add control since: ask for its equivalent by day.
  if(!back&&libReturn instanceof Element&&libReturn.dataset?.role==="add-exercise")
    back=resolveReturnFocus($$(`[data-role="add-exercise"][data-day="${CSS.escape(libReturn.dataset.day||"")}"]`).find(canTakeFocus));
  if(back===document.body||back===document.documentElement)back=null;
  libReturn=null;
  if(toProgram){
    if(returnToOnboarding){showOnboardingView();renderOnboarding()}
    else returnToTab("program")}
  // Starting the push out first ends any push in still running, which keeps
  // the page beneath inert; a Back pressed mid-arrival would otherwise find
  // nothing it could focus and leave focus on the hidden library.
  settle?.();
  // Back lands on the control that opened the library, or else on the heading of the page it returns to.
  if(!(back&&focusRoute(back)))focusRoute(routeHeading(returnToOnboarding?"onboarding":"program"))}

function renderLibrary({through=null}={}){
  if(!libFlow)return;
  const configuring=libFlow.step==="configure";
  $("#libBrowse")?.classList.toggle("hidden",configuring);
  $("#libConfigure")?.classList.toggle("hidden",!configuring);
  const title=$("#libTitle");
  if(title)title.textContent=configuring?t("library.configure_title",{day:dayLabel(libFlow.day)}):t("library.title");
  const step=$("#libStep");
  if(step){step.classList.remove("hidden");
    step.innerHTML=`<p class="libstep__lab">${esc(t("library.step",{n:configuring?2:1,total:2}))}</p>`+
      `<span class="libstep__bar${configuring?" is-done":""}" aria-hidden="true"></span>`+
      `<span class="libstep__bar${configuring?" is-done":""}" aria-hidden="true"></span>`}
  if(configuring)renderLibraryConfigure();else renderLibraryBrowse({through});
  $("#libCustom")?.classList.toggle("hidden",!!libFlow.editorScope);
  renderLibraryBar()}

function renderLibraryTabs(){
  const el=$("#libTabs");if(!el)return;
  el.innerHTML=LIB_PAGE_TABS.map(tab=>
    `<button type="button" role="tab" class="picktab${libFlow.tab===tab?" is-active":""}" `+
    `aria-selected="${libFlow.tab===tab?"true":"false"}" data-tab="${tab}">${esc(t("picker.tab."+tab))}</button>`).join("");
  $$("#libTabs .picktab").forEach(b=>b.onclick=()=>{libFlow.tab=b.dataset.tab;renderLibrary()})}

function renderLibraryFilters(){
  const el=$("#libFilters");if(!el)return;
  // Muscle and equipment are separate ideas, so they get separate rails here
  // rather than one undifferentiated row of chips.
  const chip=(kind,val,label,active)=>
    `<button type="button" class="pchip${active?" is-active":""}" data-lf="${kind}" data-val="${esc(val)}" aria-pressed="${active?"true":"false"}">${esc(label)}</button>`;
  const muscleRow=[chip("clear","",t("picker.filter_all"),!libFlow.muscle&&!libFlow.equipment)]
    .concat(PICKER_MUSCLE_GROUPS.map(([key])=>chip("muscle",key,t("picker.group."+key),libFlow.muscle===key)));
  const equipRow=PICKER_EQUIPMENT.map(eq=>chip("equipment",eq,t("picker.equipment."+eq),libFlow.equipment===eq));
  const scroller=(id,items)=>`<div id="${id}" class="pick__filters pick__filters--row" `+
    `data-allow-horizontal-scroll="x" data-horizontal-scroll-cue="partial-last-chip" tabindex="0">${items.join("")}</div>`;
  el.innerHTML=scroller("libMuscleFilters",muscleRow)+scroller("libEquipmentFilters",equipRow);
  $$("#libFilters [data-allow-horizontal-scroll]").forEach(row=>row.onkeydown=(event)=>{
    if(!["ArrowLeft","ArrowRight","Home","End"].includes(event.key))return;
    const left=event.key==="Home"?-row.scrollWidth:event.key==="End"?row.scrollWidth:event.key==="ArrowLeft"?-80:80;
    row.scrollBy({left,behavior:"auto"});event.preventDefault();
  });
  $$("#libFilters .pchip").forEach(b=>b.onclick=()=>{
    const kind=b.dataset.lf;
    if(kind==="clear"){libFlow.muscle=null;libFlow.equipment=null}
    else if(kind==="muscle")libFlow.muscle=libFlow.muscle===b.dataset.val?null:b.dataset.val;
    else libFlow.equipment=libFlow.equipment===b.dataset.val?null:b.dataset.val;
    renderLibrary()})}

function renderLibraryBrowse({through=null}={}){
  renderLibraryTabs();renderLibraryFilters();
  const list=$("#libList");if(!list)return;
  const source=libFlow.tab==="yours"?yourExercises():pickableExercises();
  const rows=source.filter(e=>exerciseMatches(e,libFlow.query,libFlow.muscle,libFlow.equipment))
    .sort((a,b)=>(a.rank??50)-(b.rank??50)||libraryName(a).localeCompare(libraryName(b)));
  // The full catalog is over a thousand rows. The first screenfuls render now
  // and the rest follow a chunk per frame; a newer render abandons the old one.
  const render=++libraryRenderToken;
  // A row that focus must return to renders in the first pass.
  const needed=through?rows.findIndex(e=>e.id===through)+1:0;
  const first=Math.max(LIBRARY_FIRST_ROWS,needed);
  list.innerHTML=rows.length
    ?rows.slice(0,first).map(e=>libraryRowHtml(e)).join("")
    :`<p class="pick__empty">${esc(t("picker.empty",{q:libFlow.query}))}</p>`;
  let next=first;
  const appendChunk=()=>{
    if(!libFlow||render!==libraryRenderToken||!list.isConnected||next>=rows.length)return;
    list.insertAdjacentHTML("beforeend",rows.slice(next,next+LIBRARY_CHUNK_ROWS).map(e=>libraryRowHtml(e)).join(""));
    next+=LIBRARY_CHUNK_ROWS;requestAnimationFrame(appendChunk)};
  // The rest waits until the view's push has settled, so it never competes
  // with the transition for frames.
  if(next<rows.length)setTimeout(()=>requestAnimationFrame(appendChunk),LIBRARY_DEFER_MS);
  // One delegated handler serves every row, however many chunks arrive.
  list.onclick=event=>{
    const toggle=event.target.closest?.("[data-lib-toggle]");if(toggle)return toggleLibrarySelection(toggle.dataset.libToggle);
    const preview=event.target.closest?.("[data-lib-preview]");if(preview)return openExercisePreview(preview.dataset.libPreview);
    const edit=event.target.closest?.("[data-lib-edit]");if(edit)return editCustomExercise(edit.dataset.libEdit)}}
const LIBRARY_FIRST_ROWS=40,LIBRARY_CHUNK_ROWS=80,LIBRARY_DEFER_MS=450;
let libraryRenderToken=0;

function libraryRowHtml(e){
  const on=libFlow.selected.has(e.id);
  const mus=[libraryMuscleAttribution(e,"primary"),libraryMuscleAttribution(e,"secondary")].filter(Boolean).join(",").split(",").filter(Boolean).slice(0,2).map(muscleLabel);
  const eq=(e.equipment||[])[0];
  const meta=[mus.join(" · "),eq?t("picker.equipment."+eq):""].filter(Boolean).join(" · ");
  return `<div class="librow${on?" is-selected":""}" data-lib-row="${esc(e.id)}">`+
    `<button type="button" class="librow__preview" data-lib-preview="${esc(e.id)}" aria-label="${esc(t("library.preview_aria",{name:libraryName(e)}))}">`+
      exerciseThumb(e,{size:"md"})+
    `</button>`+
    `<div class="librow__text">`+
      `<p class="librow__name">${esc(libraryName(e))}</p>`+
      `<p class="librow__meta">${esc(meta)}</p>`+
      (isCustomLibraryId(e.id)&&!libFlow?.editorScope
        ?`<button type="button" class="librow__edit" data-lib-edit="${esc(e.id)}">${esc(t("library.edit"))}</button>`:"")+
    `</div>`+
    `<button type="button" class="librow__check${on?" is-on":""}" role="checkbox" aria-checked="${on?"true":"false"}" `+
      `data-lib-toggle="${esc(e.id)}" aria-label="${esc(t(on?"library.remove_aria":"library.add_aria",{name:libraryName(e)}))}"></button>`+
  `</div>`}

function toggleLibrarySelection(id){
  if(!libFlow)return;
  if(libFlow.selected.has(id))libFlow.selected.delete(id);
  else libFlow.selected.set(id,null);
  // A toggle changes one row and the bar; rebuilding the whole catalog would
  // also drop the focus the lifter's tap just put on the checkbox.
  const row=$(`#libList [data-lib-row="${CSS.escape(id)}"]`);
  if(!row||libFlow.step==="configure")return renderLibrary();
  const entry=libraryEntry(id),on=libFlow.selected.has(id),check=row.querySelector("[data-lib-toggle]");
  row.classList.toggle("is-selected",on);
  if(check){check.classList.toggle("is-on",on);check.setAttribute("aria-checked",on?"true":"false");
    check.setAttribute("aria-label",t(on?"library.remove_aria":"library.add_aria",{name:libraryName(entry)}))}
  renderLibraryBar()}

function renderLibraryBar(){
  const bar=$("#libBar"),count=$("#libBarCount"),primary=$("#libPrimary");
  if(!bar||!primary)return;
  const n=libFlow.selected.size;
  bar.classList.toggle("is-hidden",n===0);
  if(count)count.textContent=n?t("library.selected",{n}):"";
  primary.textContent=libFlow.step==="configure"
    ?t("library.save_day",{day:dayLabel(libFlow.day)})
    :t("library.add_n",{n,day:dayLabel(libFlow.day)});
  primary.disabled=n===0;
  syncLibraryBarClearance()}
function syncLibraryBarClearance(){
  const bar=$("#libBar"),wrap=$("#library .libwrap");if(!bar||!wrap)return;
  if(bar.classList.contains("is-hidden")){wrap.style.removeProperty("--libbar-clearance");return}
  wrap.style.setProperty("--libbar-clearance",`${Math.ceil(bar.getBoundingClientRect().height+16)}px`)}
window.addEventListener("resize",syncLibraryBarClearance,{passive:true});

/* ---- configure step ---- */

function libraryConfigureRows(){
  return [...libFlow.selected.entries()].map(([id,cfg])=>{
    const entry=libraryEntry(id);
    return{id,entry,cfg:cfg||{sets:3,min:6,max:10}}}).filter(r=>r.entry)}

function renderLibraryConfigure(){
  const el=$("#libConfigureRows");if(!el)return;
  const rows=libraryConfigureRows();
  const count=$("#libConfigureCount");
  if(count)count.textContent=t("library.configure_count",
    {exercises:countText("exercises",rows.length),sets:countText("sets",rows.reduce((a,r)=>a+r.cfg.sets,0))});
  el.innerHTML=rows.map(r=>
    `<div class="libcfg" data-cfg="${esc(r.id)}">`+
      exerciseThumb(r.entry,{size:"md"})+
      `<div class="libcfg__body">`+
        `<p class="libcfg__name">${esc(libraryName(r.entry))}</p>`+
        `<div class="libcfg__fields">`+
          `<label class="libcfg__field"><span>${esc(t("program.exercise.sets"))}</span>`+
            `<input type="number" inputmode="numeric" min="1" step="1" data-cfg-id="${esc(r.id)}" data-cfg-field="sets" value="${r.cfg.sets}"></label>`+
          `<label class="libcfg__field"><span>${esc(t("program.exercise.min_reps"))}</span>`+
            `<input type="number" inputmode="numeric" min="1" step="1" data-cfg-id="${esc(r.id)}" data-cfg-field="min" value="${r.cfg.min}"></label>`+
          `<label class="libcfg__field"><span>${esc(t("program.exercise.max_reps"))}</span>`+
            `<input type="number" inputmode="numeric" min="1" step="1" data-cfg-id="${esc(r.id)}" data-cfg-field="max" value="${r.cfg.max}"></label>`+
        `</div>`+
      `</div>`+
      `<button type="button" class="libcfg__drop" data-cfg-drop="${esc(r.id)}" aria-label="${esc(t("library.remove_aria",{name:libraryName(r.entry)}))}">`+
        `<span class="icon-mask icon-mask--sm icon-mask--close" aria-hidden="true"></span></button>`+
    `</div>`).join("");
  $$("#libConfigureRows [data-cfg-field]").forEach(inp=>{
    inp.onfocus=()=>inp.select();
    inp.oninput=()=>{
      const id=inp.dataset.cfgId,field=inp.dataset.cfgField;
      const cur=libFlow.selected.get(id)||{sets:3,min:6,max:10};
      const next=Object.assign({},cur,{[field]:Exercise.posInt(inp.value,cur[field])});
      if(next.max<next.min)next.max=next.min;
      libFlow.selected.set(id,next)}});
  $$("#libConfigureRows [data-cfg-drop]").forEach(b=>b.onclick=()=>{
    libFlow.selected.delete(b.dataset.cfgDrop);
    if(!libFlow.selected.size){libFlow.step="browse"}
    renderLibrary()})}

async function commitLibrarySelection(){
  if(!libFlow||!libFlow.selected.size)return null;
  if(libFlow.step!=="configure"){libFlow.step="configure";renderLibrary();window.scrollTo({top:0});return null}
  const rows=libraryConfigureRows();
  const editorScope=!!libFlow.editorScope;
  const proposal=libFlow.editorScope?programEditorSnapshot():cloneSnapshot(state);
  const nextProgram=makeProgram(proposal.program,null,proposal.programMeta);
  const baseline=cloneSnapshot(proposal),addedIds=[];
  for(const r of rows){
    const added=nextProgram.addExercise(libFlow.day,r.entry);
    added.sets=r.cfg.sets;added.min=r.cfg.min;added.max=Math.max(r.cfg.min,r.cfg.max);addedIds.push(added.id)}
  proposal.program=nextProgram.toJSON();
  // The canonical definition is the program; each added row becomes a slot
  // through the same intent the editor's own Add uses.
  for(const id of addedIds){
    const cycleIndex=mesocycleLifecycle(proposal.programMeta).current||1;
    if(!syncEditorCanonicalIntent(proposal,baseline,{kind:"exercise_add",targetId:id,targetDay:libFlow.day},{cycleIndex})){
      toast(t("toast.program_save_failed"));return{ok:false,invalid:true,code:"invalid_canonical_editor_intent"}}}
  const result=libFlow.editorScope
    ?await commitProgramEditorProposal(proposal)
    :await commitProposedState(proposal);
  const setupDraftAccepted=editorScope&&setupEditorOpen&&result?.setupDraft===true&&
    result?.localOk===true&&result?.idbOk===true;
  if(!(result?.committed===true&&result?.settled===true)&&!setupDraftAccepted){
    toast(t("toast.program_save_failed"));return result}
  const n=rows.length,target=libFlow.day;
  setDayCollapsed(target,false);
  closeLibrary({toProgram:true});
  if(editorScope&&setupEditorOpen){
    // The full-library detour commits through the shared program-editor
    // transaction, while the setup editor still owns its private document. Pull
    // the committed candidate back into that editor before the next action.
    // Every edit made before the detour was already staged in this same setup
    // draft, so discard here is a synchronization operation, not user-facing
    // data loss. A normal refresh would correctly report an external change as
    // a conflict because the editor's baseline is still the pre-detour copy.
    onboardingProgramEditor?.discard?.();
    updateOnboardingEditorActions();
  }else render();
  toast(tOne("toast.exercises_added",n));
  return result}

/* ---- exercise preview ---- */

function openExercisePreview(id){
  const entry=libraryEntry(id);if(!entry)return;
  previewState={id,from:libFlow?"library":"picker",returnId:id};
  const settle=routePushBegin("in",{pushed:$("#exercisePreview"),under:routeViewEl(currentViewId())});
  document.body.classList.add("is-preview");
  $$(".view").forEach(v=>v.classList.toggle("active",v.id==="exercisePreview"));
  window.scrollTo({top:0});
  renderExercisePreview();
  $("#previewBack")?.focus({preventScroll:true});
  settle?.()}

function closeExercisePreview(){
  const back=previewState?.from,returnId=previewState?.returnId;
  previewState=null;
  const settle=routePushBegin("out",{pushed:$("#exercisePreview"),under:routeViewEl(back==="library"&&libFlow?"library":"program")});
  document.body.classList.remove("is-preview");
  if(back==="library"&&libFlow){$$(".view").forEach(v=>v.classList.toggle("active",v.id==="library"));renderLibrary({through:returnId});
    requestAnimationFrame(()=>{const target=$(`[data-lib-preview="${CSS.escape(returnId||"")}"]`);if(target)target.focus({preventScroll:true})})}
  else{document.body.classList.remove("is-library");returnToTab("program")}
  settle?.()}

function renderExercisePreview(){
  const el=$("#previewBody");if(!el||!previewState)return;
  const e=libraryEntry(previewState.id);if(!e)return;
  const prim=muscles(libraryMuscleAttribution(e,"primary")).map(muscleLabel).join(" · ");
  const sec=muscles(libraryMuscleAttribution(e,"secondary")).map(muscleLabel).join(" · ");
  const eq=(e.equipment||[]).map(x=>t("picker.equipment."+x)).join(" · ");
  const inLibrary=!!libFlow;
  const selected=inLibrary&&libFlow.selected.has(e.id);
  el.innerHTML=
    `<p class="preview__eyebrow">${esc(prim)}</p>`+
    `<h2 class="preview__title">${esc(libraryName(e))}</h2>`+
    `<p class="preview__sub">${esc(eq)}</p>`+
    // A large illustration carries instructional content, so it is described
    // rather than hidden; the empty tile has nothing to describe.
    (exerciseMedia(e)
      ?`<img class="exthumb exthumb--lg" src="${esc(exerciseMedia(e))}" alt="${esc(t("preview.art_alt",{name:libraryName(e)}))}" decoding="async" width="768" height="768">`
      :`<span class="exthumb exthumb--lg exthumb--empty" aria-hidden="true"><span class="icon-mask icon-mask--dumbbell"></span></span>`)+
    `<h3 class="preview__head">${esc(t("preview.muscles"))}</h3>`+
    `<dl class="preview__rows">`+
      `<div class="preview__row"><dt>${esc(t("program.exercise.primary"))}</dt><dd>${esc(prim||"—")}</dd></div>`+
      `<div class="preview__row"><dt>${esc(t("program.exercise.secondary"))}</dt><dd>${esc(sec||"—")}</dd></div>`+
    `</dl>`+
    (e.notes?`<h3 class="preview__head">${esc(t("program.exercise.setup_notes"))}</h3><p class="preview__notes">${esc(e.notes)}</p>`:"")+
    (inLibrary
      ?`<button type="button" class="btn btn--cta" id="previewAdd">${esc(t(selected?"preview.remove":"preview.add",{day:dayLabel(libFlow.day)}))}</button>`
      :"");
  const add=$("#previewAdd");
  if(add)add.onclick=()=>{toggleLibrarySelection(e.id);closeExercisePreview()}}

// @ci-domain entry,program,settings
/* ---- Import review screen ---- */

const importStatusKey={[IMPORT_EXACT]:"import.status.exact",[IMPORT_ALIAS]:"import.status.alias",
  [IMPORT_PROBABLE]:"import.status.probable",[IMPORT_UNMATCHED]:"import.status.unmatched"};

function renderImportReview(){
  if(!importDraft)return;
  const counts=importCounts(importDraft);
  const file=$("#importFile");
  if(file)file.textContent=t("import.file",{name:importDraft.fileName||t("import.file_fallback"),n:counts.total,exercise:tp(counts.total,"lift")});
  const notImportedEl=$("#importNotImported");
  if(notImportedEl){
    if(importDraft?.notImported?.length){
      const items=importDraft.notImported.map(cat=>t(FREEFORM_NOT_IMPORTED_KEYS[cat]||"entry.freeform.not_imported.other_notes")).join(", ");
      notImportedEl.innerHTML=`<p class="entry__notice entry__notice--info" role="status">${esc(t("entry.freeform.not_imported_notice",{items}))}</p>`;
      notImportedEl.hidden=false;
    }else{
      notImportedEl.innerHTML="";
      notImportedEl.hidden=true;
    }
  }
  const originalEl=$("#importOriginalText");
  if(originalEl){
    if(importDraft?.originalText){
      originalEl.innerHTML=`<details class="entry__original-text"><summary>${esc(t("entry.freeform.view_original"))}</summary><pre class="entry__pre">${esc(importDraft.originalText)}</pre></details>`;
      originalEl.hidden=false;
    }else{
      originalEl.innerHTML="";
      originalEl.hidden=true;
    }
  }
  const countsEl=$("#importCounts");
  if(countsEl)countsEl.innerHTML=
    `<span class="impcount"><b>${counts.linked}</b>${esc(t("import.count_linked"))}</span>`+
    `<span class="impcount"><b>${counts.review}</b>${esc(t("import.count_review"))}</span>`+
    `<span class="impcount"><b>${counts.custom}</b>${esc(t("import.count_custom"))}</span>`;
  const rows=$("#importRows");
  if(rows){
    // Rows still needing a decision come first: they are the only reason this
    // screen exists, and a twelve-exercise split should not hide them.
    const ordered=[...importDraft.rows].sort((a,b)=>(a.reviewed?1:0)-(b.reviewed?1:0));
    rows.innerHTML=ordered.map(importRowHtml).join("");
    $$("#importRows [data-imp-act]").forEach(b=>
      b.onclick=()=>importRowAction(b.dataset.impAct,b.dataset.impKey,b.dataset.impIdx));
  }
  /* The one primary lives in the pinned region. While rows still need a
     decision it is disabled, drops its arrow, and the count says why directly
     above it, the same way every route's pinned action does. */
  const commit=$("#importCommit"),reason=$("#importCommitReason");
  if(commit){
    const blocked=counts.review>0;
    commit.disabled=blocked;
    commit.textContent=t("entry.preview.review");
    commit.classList.toggle("btn--noarrow",blocked);
    if(blocked)commit.setAttribute("aria-describedby","importCommitReason");
    else commit.removeAttribute("aria-describedby");
    if(reason){
      reason.hidden=!blocked;
      reason.textContent=blocked?t("import.commit_blocked",{n:counts.review}):""}}
}

function importRowHtml(row){
  // An unreviewed row shows what is being proposed, not the standing default:
  // "keep as imported" beside a Likely badge hides the very thing being asked
  // about. Once decided, the target is the decision.
  const proposed=!row.reviewed&&row.match?row.match:null;
  const shown=row.decision==="link"&&row.match?row.match:proposed;
  const target=shown?libraryName(shown)
    :row.decision==="custom"?t("import.target_custom")
    :t("import.target_raw");
  const badge=row.reviewed
    ?`<span class="impbadge is-done">${esc(t("import.status.confirmed"))}</span>`
    :`<span class="impbadge is-open">${esc(t(importStatusKey[row.status]||"import.status.unmatched"))}</span>`;
  const art=shown?exerciseThumb(shown,{size:"sm"}):emptyThumb({size:"sm"});
  // A settled row keeps its name, its target, its art and its badge, and trades
  // its three remaining alternatives for one quiet way back in. Most settled
  // rows were matched by the importer rather than chosen by the lifter, so the
  // alternatives are noise on the screen you read before replacing a program.
  const folded=row.reviewed&&!row.expanded;
  // Scoring puts the right movement in the shortlist far more reliably than it
  // puts it first, and a line like "Hack squat" never says whether the barbell
  // or the machine is meant. So an undecided row offers its candidates instead
  // of a verdict, and the escape hatches move behind a disclosure rather than
  // wrapping four buttons onto three lines of a phone.
  const shortlist=(row.shortlist||[]).filter(Boolean);
  const chips=!folded&&shortlist.length
    ?shortlist.map((entry,i)=>
      `<button type="button" class="improw__btn improw__btn--pick" data-imp-act="pick" data-imp-idx="${i}" data-imp-key="${esc(row.key)}">${esc(t("import.action_link",{name:libraryName(entry)}))}</button>`).join("")
    :(!folded&&row.match&&row.decision!=="link"
      ?`<button type="button" class="improw__btn" data-imp-act="link" data-imp-key="${esc(row.key)}">${esc(t("import.action_link",{name:libraryName(row.match)}))}</button>`:"");
  const escapes=
    // Every slot of a program names a movement, so an unmatched row is settled
    // by choosing one or creating it; there is no unlinked "keep as typed".
    `<button type="button" class="improw__btn" data-imp-act="choose" data-imp-key="${esc(row.key)}">${esc(t("import.action_choose"))}</button>`+
    (row.decision!=="custom"
      ?`<button type="button" class="improw__btn" data-imp-act="custom" data-imp-key="${esc(row.key)}">${esc(t("import.action_custom"))}</button>`:"");
  const acts=folded
    ?`<button type="button" class="improw__btn improw__btn--change" data-imp-act="expand" data-imp-key="${esc(row.key)}">${esc(t("import.action_change"))}</button>`
    :chips+(chips
      ?`<details class="improw__more"><summary>${esc(t("import.more_options"))}</summary><div class="improw__acts">${escapes}</div></details>`
      :escapes);
  return `<div class="improw${row.reviewed?"":" is-open"}${folded?" is-folded":""}" data-imp-row="${esc(row.key)}">`+
    `<p class="improw__from">${esc(row.raw.name||"")}</p>`+
    `<span class="improw__arrow" aria-hidden="true">→</span>`+
    art+
    `<div class="improw__to"><p class="improw__name">${esc(target)}</p>${badge}</div>`+
    `<div class="improw__acts">${acts}</div>`+
  `</div>`}

function importRowAction(act,key,idx){
  const row=importDraft?.rows.find(r=>r.key===key);
  if(!row)return;
  // Change only reopens the row: the decision it already carries is untouched,
  // so a lifter who taps it and changes their mind still imports what they saw.
  // The render replaces the row's markup, so the caret is put back on the
  // controls the tap was asking for rather than dropped to the document.
  if(act==="expand"){row.expanded=true;renderImportReview();
    $(`#importRows [data-imp-row="${esc(row.key)}"] [data-imp-act]`)?.focus({preventScroll:true});return}
  if(act==="pick"){
    const entry=(row.shortlist||[])[Number(idx)];
    if(!entry)return;
    row.match=entry;row.decision="link";
    settleImportRow(row,Number(idx)===0?"top_candidate":"alternate");
    return}
  if(act==="link"&&row.match){row.decision="link";settleImportRow(row,"top_candidate");return}
  if(act==="choose"){
    openExercisePicker({title:t("import.pick_title"),subtitle:row.raw.name||"",
      onPick:entry=>{row.match=entry;row.decision="link";settleImportRow(row,"picker")}});
    return}
  if(act==="custom"){
    // Creating the definition here rather than at commit time means the lifter
    // sees exactly what will exist before anything is written.
    openCustomExerciseSheet({entry:{name:row.raw.name||"",primary:row.raw.primary||"",secondary:row.raw.secondary||""},
      stageOnly:true,
      onSave:entry=>{row.createdCustom=entry;row.createdCustomId=entry.id;
        row.decision="custom";settleImportRow(row,"custom")}})}}
/** A decided row folds back down: the alternatives have done their job.
 *  How it was decided is the only measure of whether matching improved for
 *  programs we have never seen. Categorical, and never the exercise name. */
function settleImportRow(row,method){
  if(method&&!row.reviewed)
    captureEvent("program_import_row_resolved",
      {method,source:importDraft?.sourceType==="freeform"?"freeform":"file"});
  row.reviewed=true;row.expanded=false;renderImportReview()}

function ensureImportEntryFlow(draft){
  if(entryState?.route==="import"&&entryState.step==="import_source")return;
  const origin=draft?.fromFirstRun?"first-run":hasActiveProgram()?"settings":"first-run";
  startOnboarding(origin,{userInitiated:true});
  if(entryState?.route!=="import"||entryState.step!=="import_source")entrySelectRoute("import")}

function openImportReview(draft){
  ensureImportEntryFlow(draft);
  draft.onboarding=true;
  importDraft=draft;
  captureEvent("program_import_review_reached",{source:draft?.sourceType==="freeform"?"freeform":"file"});
  importReturn=document.activeElement;
  // The review renders inside the app shell, so the first-run gate steps aside
  // for it rather than covering it.
  if(draft?.fromFirstRun)suspendFirstRun();
  document.body.classList.add("is-import");
  $$(".view").forEach(v=>v.classList.toggle("active",v.id==="importReview"));
  window.scrollTo({top:0});
  // The review is its own scroll container, like the route it belongs to.
  const reviewView=$("#importReview");if(reviewView)reviewView.scrollTop=0;
  renderImportReview();
  const counts=importCounts(draft),target=counts.review
    ?$("#importRows .improw.is-open [data-imp-act]")
    :$("#importCommit");
  (target||$("#importBack"))?.focus({preventScroll:true})}

function closeImportReview({toProgram=true}={}){
  const wasOnboarding=importDraft?.onboarding,wasFirstRun=importDraft?.fromFirstRun;
  importDraft=null;
  document.body.classList.remove("is-import");
  const back=resolveReturnFocus(importReturn);
  importReturn=null;
  // Backing out of an import started during onboarding returns to onboarding —
  // or to the setup gate it came from. Either way the lifter has no program yet,
  // so they cannot be dropped into the app.
  if(wasFirstRun&&toProgram){openFirstRun();return}
  if(wasOnboarding&&toProgram){showOnboardingView();renderOnboarding();return}
  if(toProgram)returnToTab("program");
  if(back)try{back.focus({preventScroll:true})}catch{}}

function importCandidate(draft){
  const exercises=importDraftExercises(draft);
  const proposal=cloneSnapshot(state);
  const merged=mergeImportedCustomExercises(importDraftCustomDefinitions(draft),exercises,proposal);
  const program=new Program(exercises,snapshotLookup(merged.customExercises)).toJSON();
  const carriedDefinition=remapDefinitionMovements(draft.definition,merged.remap);
  const wantedCustomIds=new Set([...program.map(exercise=>exercise.libraryId),...definitionMovementIds(carriedDefinition)]
    .filter(isCustomLibraryId));
  const candidateCustomExercises=merged.customExercises
    .filter(entry=>wantedCustomIds.has(entry.id)).map(cloneSnapshot);
  const structure=draft.meta?.programStructure?cloneSnapshot(draft.meta.programStructure):null;
  const structureDays=Array.isArray(structure?.days)?structure.days:[];
  const labels=structureDays.length?structureDays.map(item=>item.label||item.dayId):
    [...new Set(program.map(exercise=>exercise.day))];
  const days=labels.filter(Boolean).map((label,index)=>({
    dayId:structureDays[index]?.dayId||label,label,
    exercises:program.filter(exercise=>exercise.day===label).map(cloneSnapshot),
  }));
  const progressionIncompatibilities=Array.isArray(draft.meta?.progressionIncompatibilities)
    ?cloneSnapshot(draft.meta.progressionIncompatibilities):[];
  const progressionData=candidateProgressionData(draft.meta?.progressionRelations,program,
    progressionIncompatibilities,"program-import");
  const progressionModifiers=normalizeProgressionModifiers(draft.meta?.progressionModifiers,{
    preserveInvalid:true,incompatibilities:progressionData.incompatibilities,source:"program-json"});
  // An imported program becomes a Build definition over the matched catalog
  // movements and custom definitions; the preview rows are its projection.
  const kept=draft.definition&&draft.rows.every(row=>row.decision==="link"&&row.match?.id===row.raw.libraryId);
  const programDefinition=kept?canonicalProgramDefinition(carriedDefinition,candidateCustomExercises)
    :manualProgramDefinitionFromRows(program,labels,candidateCustomExercises);
  const projected=programDefinition?flatProgramFromDefinition(programDefinition,candidateCustomExercises,1):program;
  const projectedDays=programDefinition?programDefinition.days.filter(day=>day.kind==="training").map((day,index)=>({
    dayId:day.id,label:day.name,order:index+1,exercises:projected.filter(row=>row.dayId===day.id).map(cloneSnapshot)})):days;
  return{
    program:projected,
    days:projectedDays,
    ...(programDefinition?{programDefinition}:{}),
    programStructure:programDefinition?{schemaVersion:1,days:projectedDays.map(({dayId,label,order})=>({dayId,label,order})),
      provenance:{source:"import"}}:structure,
    progressionRelations:progressionData.relations,
    progressionModifiers,
    progressionIncompatibilities:progressionData.incompatibilities,
    customExercises:candidateCustomExercises,
    source:"import",
    format:draft.format,
  }}

/* Review decisions become an owned setup candidate. Durable active state moves
   only through the common explicit activation transaction on the next screen. */
// @ci-domain global
async function commitImportReview(){
  if(!importDraft)return null;
  const counts=importCounts(importDraft);
  if(counts.review>0){toast(t("toast.import_needs_review",{n:counts.review,exercise:tp(counts.review,"lift")}));return null}
  const draft=importDraft;
  setStagedImportSource(draft.sourceType);
  ensureImportEntryFlow(draft);
  const preview=importCandidate(draft);
  const name=typeof draft.meta?.name==="string"?draft.meta.name.trim():"";
  let next=ProgramEntry.setAnswers(entryState,{importReady:true});
  next={...next,versions:entryVersions()};
  next=ProgramEntry.setResult(next,{
    fingerprint:entryCandidateFingerprint("import",name,preview),
    selected:{id:"import",source:"import"},
    name,
    preview,
  });
  next=ProgramEntry.advance(next).state;
  // Keep the in-memory state in lockstep with the staged draft. Every import,
  // including an unversioned first-run program file, remains a candidate until
  // the common preview's explicit activation action is chosen.
  entryState=next;
  const saved=await persistSetupDraft(next);
  if(!saved?.ok){toast(t("toast.program_import_failed"));return saved}
  closeImportReview({toProgram:false});
  entryUiNotice=null;
  showOnboardingView();renderOnboarding();
  // The original unversioned program-file door now converges with versioned
  // onboarding imports: both leave the active state untouched until the
  // preview's explicit activation transaction runs.
  return{localOk:false,idbOk:false,staged:true,setupDraft:true}}

/* A backup is not a program file. It carries the log, the settings and the meta
   as well as the program, so reading only its exercises drops the rest on the
   floor — silently, because the review screen has nothing to show for a key it
   never looked at. An empty log is no reason to demote one: the language, the
   rest timer, the RIR mode and the program's own name and block are still in
   there, and the lifter restoring onto a fresh install has nothing else left to
   read them out of. Recognised here so the program door can offer the restore
   instead of quietly discarding it. */
function parseBackupFile(text){
  const parsed=boundedImportJson(text,{maxBytes:BACKUP_MAX_BYTES,maxNodes:BACKUP_MAX_NODES});
  return isImportableState(parsed)?parsed:null}

/* Reading a file no longer changes anything: it opens the review screen. The
   old path linked names and wrote the program behind one confirm(), which meant
   a wrong file had already replaced the program by the time you saw it. */
async function importProgramFile(e,io){const f=e.target.files?.[0];if(!f)return;
  try{
    if(Number.isFinite(f.size)&&f.size>BACKUP_MAX_BYTES)throw Error();
    const text=await f.text();
    const parsedBackup=parseBackupFile(text),legacyBackup=isLegacyBackup(parsedBackup);
    const backup=legacyBackup?null:parsedBackup;
    const source=parseProgramSource(text,f.name);
    if(legacyBackup&&!source?.exercises?.length){toast(t("toast.backup_legacy"));e.target.value="";return}
    // A backup whose program is empty is still a backup worth restoring, so the
    // exercise requirement only has to hold for a file that is nothing else.
    if(!backup&&!source?.exercises?.length)throw Error();
    pendingImportIo=io||null;
    let draft=null;
    if(source?.exercises?.length){
      draft=buildImportDraft(source,f.name);
      // An import during onboarding still finishes onboarding: it is how a lifter
      // brings their own split instead of generating one. The setup gate's Import
      // is the same first run by another door, so it commits the same way and
      // returns to the gate if it is abandoned. The review comes first either way.
      draft.fromFirstRun=firstRunOpen();
      draft.onboarding=draft.fromFirstRun||!!$("#onboarding")?.classList.contains("active")}
    if(backup)
      // The button said "program", so program-only stays on the table — but
      // what else the file is carrying is now named out loud and can be
      // restored instead.
      openImportChoice(Object.assign(importChoiceContext(backup,e.target,io),
        {bodyKey:"dialog.import.body_program",programOnly:draft?()=>openImportReview(draft):null}));
    else openImportReview(draft);
  }catch{toast(t("toast.program_import_invalid"))}
  e.target.value=""}
let pendingImportIo=null;
// @ci-domain entry
/* ---- Free-form program import ----
 * A program a lifter already owns often exists only as a coach's message, a
 * spreadsheet dump or a note to self. Retyping it into the editor is where
 * setup gets abandoned, and Taurifer has no model of its own to read it with.
 * So the conversion is handed to an assistant the lifter already has on their
 * phone, deliberately and by hand: Taurifer writes the prompt around what was
 * pasted, the lifter taps ChatGPT or Claude, and the reply comes back through
 * the same import review a file goes through.
 *
 * This is not an integration. There is no key, no account and no request from
 * this app: the only thing that leaves the device is the text the lifter chose
 * to send, in a link they tapped. The pasted text and the reply live in memory
 * for the length of the flow; only which of the two doors was last used is
 * remembered, as a device-only UI pref. Neither is persisted, exported or
 * logged. See docs/adr/0014-free-form-program-import-handoff.md.
 */
const FREEFORM_MAX_CHARS=12000;
/* Past this the prefilled link stops being dependable across the two apps and
   their mobile shells, so the prompt travels on the clipboard instead. */
const FREEFORM_URL_MAX=6000;
const FREEFORM_JSON_CANDIDATES=8;
const freeformCountLabel=()=>t("entry.freeform.count",{
  n:entryFreeformInput.length.toLocaleString(locTag()),
  max:FREEFORM_MAX_CHARS.toLocaleString(locTag())});
const FREEFORM_APPS={
  chatgpt:{base:"https://chatgpt.com/",param:"q",label:"entry.freeform.open_chatgpt",copyLabel:"entry.freeform.copy_chatgpt",copiedLabel:"entry.freeform.open_chatgpt_copied"},
  claude:{base:"https://claude.ai/new",param:"q",label:"entry.freeform.open_claude",copyLabel:"entry.freeform.copy_claude",copiedLabel:"entry.freeform.open_claude_copied"},
};
const FREEFORM_NOT_IMPORTED_KEYS = {
  rest_times: "entry.freeform.not_imported.rest_times",
  rir_rpe: "entry.freeform.not_imported.rir_rpe",
  tempo: "entry.freeform.not_imported.tempo",
  supersets: "entry.freeform.not_imported.supersets",
  warmups: "entry.freeform.not_imported.warmups",
  cardio: "entry.freeform.not_imported.cardio",
  progression_rules: "entry.freeform.not_imported.progression_rules",
  deload: "entry.freeform.not_imported.deload",
  other_notes: "entry.freeform.not_imported.other_notes",
};
const FREEFORM_SESSION_KEY="repforge_freeform_session_v1";
let entryImportMode=null,entryFreeformInput="",entryFreeformReply="";
let entryFreeformStage=1,entryFreeformLastProvider=null;
let entryFreeformGapResult=null,entryFreeformGapAnswers={},entryFreeformGapErrors=new Set(),entryFreeformStatus=null;
let entryFreeformReplyInvalidated=false,entryFreeformFailReason=null;
/* The clipboard read is the only asynchronous step in this flow, so its result
   can arrive after the lifter has moved on. The epoch changes whenever the
   free-form session stops being the one the read was started for; the sequence
   number retires an older read when a newer one starts. */
let entryFreeformEpoch=0,entryFreeformClipboardSeq=0;
let entryFreeformClipboardBusy=false,entryFreeformClipboardNote=null;
const entryFreeformCopiedApps=new Set();

function loadFreeformSession(){
  try{
    const raw=sessionStorage.getItem(FREEFORM_SESSION_KEY);
    if(!raw)return false;
    const data=JSON.parse(raw);
    if(typeof data.source==="string")entryFreeformInput=data.source;
    if(typeof data.reply==="string")entryFreeformReply=data.reply;
    if(Number.isInteger(data.stage)&&data.stage>=1&&data.stage<=3)entryFreeformStage=data.stage;
    if(typeof data.lastProvider==="string")entryFreeformLastProvider=data.lastProvider;
    entryFreeformCopiedApps.clear();
    if(Array.isArray(data.copiedApps))
      for(const app of data.copiedApps)if(FREEFORM_APPS[app])entryFreeformCopiedApps.add(app);
    return true;
  }catch{
    return false;
  }
}

function saveFreeformSession(){
  try{
    if(!entryFreeformInput&&!entryFreeformReply&&entryFreeformStage===1){
      sessionStorage.removeItem(FREEFORM_SESSION_KEY);
      return;
    }
    const data={
      source:entryFreeformInput||"",
      reply:entryFreeformReply||"",
      stage:entryFreeformStage||1,
      lastProvider:entryFreeformLastProvider||null,
      copiedApps:[...entryFreeformCopiedApps],
    };
    sessionStorage.setItem(FREEFORM_SESSION_KEY,JSON.stringify(data));
  }catch{}
}

function clearFreeformSession(){
  try{sessionStorage.removeItem(FREEFORM_SESSION_KEY)}catch{}
}
/* Which door a staged import came through, kept alive from the review commit to
   the activation that happens a screen later. It cannot ride importDraft, which
   closeImportReview nulls during the commit, nor the entry result, whose import
   route allows only "selected". Tab-scoped like the freeform session, carries no
   program content, and survives a reload between review and activation. */
const IMPORT_SOURCE_KEY="repforge_import_source_v1";
function setStagedImportSource(sourceType){
  try{sessionStorage.setItem(IMPORT_SOURCE_KEY,sourceType==="freeform"?"freeform":"file")}catch{}
}
function stagedImportSource(){
  try{return sessionStorage.getItem(IMPORT_SOURCE_KEY)==="freeform"?"freeform":"file"}catch{return"file"}
}
function clearStagedImportSource(){
  try{sessionStorage.removeItem(IMPORT_SOURCE_KEY)}catch{}
}

function resetFreeformImport(){
  entryFreeformEpoch++;
  entryFreeformClipboardNote=null;
  entryFreeformInput="";
  entryFreeformReply="";
  entryFreeformStage=1;
  entryFreeformLastProvider=null;
  entryFreeformGapResult=null;
  entryFreeformGapAnswers={};
  entryFreeformGapErrors.clear();
  entryFreeformStatus=null;
  entryFreeformFailReason=null;
  entryFreeformReplyInvalidated=false;
  entryFreeformCopiedApps.clear();
  clearFreeformSession();
}
/** Which import door this device used last. A preference about this screen, so
 *  it lives with the other device-only UI prefs and never touches state. */
function importSourceMode(){
  if(!entryImportMode)entryImportMode=uiPrefs.importSourceMode==="file"?"file":"freeform";
  return entryImportMode}
function setImportSourceMode(mode,{render=true}={}){
  const prev=importSourceMode();
  if(mode==="file"&&prev==="freeform"&&(entryFreeformInput.trim().length>10||entryFreeformReply.trim().length>10)){
    if(!confirm(t("entry.freeform.confirm_discard")))return;
  }
  entryImportMode=mode==="freeform"?"freeform":"file";
  setUiPref("importSourceMode",entryImportMode);
  // Clearing only the stored copy left the text in memory, so a lifter who
  // confirmed the discard got it back by switching doors again.
  if(entryImportMode==="file")resetFreeformImport();
  else loadFreeformSession();
  if(render)renderOnboarding()}
const freeformProgram=()=>String(entryFreeformInput||"").trim();
/** The prompt is one localized string: the lifter reads what they are sending
 *  before they send it, and the translation is reviewed like any other copy. */
function freeformPrompt(program=freeformProgram()){
  return t("entry.freeform.prompt",{program})}
/** The prefilled link, or null when the prompt is too long to travel in a URL. */
function freeformAppUrl(app,prompt){
  const spec=FREEFORM_APPS[app];
  if(!spec||!prompt)return null;
  const url=`${spec.base}?${spec.param}=${encodeURIComponent(prompt)}`;
  return url.length<=FREEFORM_URL_MAX?url:null}
function freeformAppHref(app,program=freeformProgram()){
  const spec=FREEFORM_APPS[app];
  if(!spec)return"";
  return(program&&freeformAppUrl(app,freeformPrompt(program)))||spec.base}

/* Candidate JSON values inside a chat reply, so "Here you go:" and a fenced
   block cost nobody an import. Fenced blocks first, then every balanced
   top-level object or array, bounded like any other import. Each candidate is
   whole: a fence body, or a root that never closes, is kept as one candidate
   so its nested pieces can never import on their own. A backslash pasted just
   before a root stays in it, so the illegal escape fails to parse. */
function freeformJsonCandidates(text){
  const out=[],fences=[];
  const fence=/```(?:json)?\s*([\s\S]*?)(?:```|$)/gi;
  for(let match;out.length<FREEFORM_JSON_CANDIDATES&&(match=fence.exec(text))!==null;){
    fences.push([match.index,fence.lastIndex]);
    const body=match[1].trim();
    if(body)out.push(body)}
  const closers={"{":"}","[":"]"};
  for(let i=0;i<text.length&&out.length<FREEFORM_JSON_CANDIDATES;i++){
    const inFence=fences.find(([start,end])=>i>=start&&i<end);
    if(inFence){i=inFence[1]-1;continue}
    const open=text[i],close=closers[open];
    if(!close)continue;
    const start=text[i-1]==="\\"?i-1:i;
    let depth=0,inString=false,escaped=false,closed=false;
    for(let j=i;j<text.length;j++){
      const ch=text[j];
      if(inString){
        if(escaped)escaped=false;
        else if(ch==="\\")escaped=true;
        else if(ch==='"')inString=false;
        continue}
      if(ch==='"'){inString=true;continue}
      if(ch===open)depth++;
      else if(ch===close&&--depth===0){out.push(text.slice(start,j+1));i=j;closed=true;break}}
    if(!closed){out.push(text.slice(start));break}}
  return out}
function extractNotImported(obj){
  if(!obj||typeof obj!=="object")return[];
  const raw=Array.isArray(obj.notImported)?obj.notImported:[];
  const grammar=window.RepForgeUnsupportedWorkoutGrammar;
  return grammar?.recognizedForDisplay
    ?grammar.recognizedForDisplay(raw,Object.keys(FREEFORM_NOT_IMPORTED_KEYS))
    :[]}

function captureUnsupportedWorkoutConcepts(sidecar){
  const grammar=window.RepForgeUnsupportedWorkoutGrammar;
  if(!grammar?.normalize)return;
  for(const category of grammar.normalize(sidecar))
    captureEvent("program_import_unsupported_concept",{category})}

function parseRepsInput(str){
  if(typeof str!=="string"&&typeof str!=="number")return null;
  const s=String(str).trim();
  const mRange=s.match(/^(\d+)\s*(?:[-–—/]|to)\s*(\d+)$/i);
  if(mRange){
    const min=parseInt(mRange[1],10),max=parseInt(mRange[2],10);
    if(min>=1&&min<=1000&&max>=min&&max<=1000)return{min,max};
    return null}
  const mSingle=s.match(/^(\d+)$/);
  if(mSingle){
    const val=parseInt(mSingle[1],10);
    if(val>=1&&val<=1000)return{min:val,max:val}}
  return null}

function parseSetsInput(str){
  if(typeof str!=="string"&&typeof str!=="number")return null;
  const s=String(str).trim();
  if(!/^\d+$/.test(s))return null;
  const n=parseInt(s,10);
  return(n>=1&&n<=100)?n:null}

/* Gaps are keyed by row position, never by (day, order): a reply that numbers
   some rows and omits others collides on that pair, and two rows sharing a key
   means one entered number silently lands on a second exercise. */
function readFreeformGapEnvelope(candidate){
  let raw=null;
  if(typeof candidate==="string"){
    const trimmed=candidate.trim();
    if(!trimmed.startsWith("{")&&!trimmed.startsWith("["))return null;
    raw=boundedImportJson(trimmed);
  }else if(candidate&&typeof candidate==="object"){
    raw=candidate;
  }
  if(!raw||typeof raw!=="object"||Array.isArray(raw))return null;
  const exercises=Array.isArray(raw.exercises)?raw.exercises:(Array.isArray(raw.program)?raw.program:null);
  if(!Array.isArray(exercises)||!exercises.length||exercises.length>IMPORT_MAX_NODES)return null;

  const normalized=[];
  const orders=new Map();
  for(let i=0;i<exercises.length;i++){
    const row=exercises[i];
    if(!row||typeof row!=="object"||Array.isArray(row))return null;
    const day=typeof row.day==="string"?row.day.trim():"";
    const name=typeof row.name==="string"?row.name.trim():"";
    if(!day||!name)return null;

    let order=row.order;
    if(order===undefined||order===null){
      const next=(orders.get(day)||0)+1;
      orders.set(day,next);
      order=next;
    }else if(!Number.isInteger(order)||order<1||order>1000){
      return null;
    }

    let sets=row.sets;
    let setsValid=Number.isInteger(sets)&&sets>=1&&sets<=100;
    if(sets!==undefined&&sets!==null&&!setsValid)return null;

    let min=row.min??row.repLow;
    let max=row.max??row.repHigh;
    let minValid=Number.isInteger(min)&&min>=1&&min<=1000;
    let maxValid=Number.isInteger(max)&&max>=1&&max<=1000&&(!minValid||max>=min);
    let repsValid=minValid&&maxValid;
    if((min!==undefined&&min!==null&&!minValid)||(max!==undefined&&max!==null&&!maxValid))return null;

    normalized.push({
      day,
      name,
      order,
      sets:setsValid?sets:undefined,
      min:repsValid?min:undefined,
      max:repsValid?max:undefined,
      libraryId:typeof row.libraryId==="string"?row.libraryId:undefined,
    });
  }

  const missingSidecar=Array.isArray(raw.missing)?raw.missing:[];
  const gaps=[];
  for(let i=0;i<normalized.length;i++){
    const r=normalized[i];
    const sidecarSets=missingSidecar.some(m=>m&&m.day===r.day&&m.order===r.order&&m.field==="sets");
    const sidecarReps=missingSidecar.some(m=>m&&m.day===r.day&&m.order===r.order&&m.field==="reps");

    if(r.sets===undefined||sidecarSets){
      gaps.push({
        key:`${i}::sets`,
        rowIndex:i,
        day:r.day,
        order:r.order,
        name:r.name,
        field:"sets",
      });
    }
    if(r.min===undefined||r.max===undefined||sidecarReps){
      gaps.push({
        key:`${i}::reps`,
        rowIndex:i,
        day:r.day,
        order:r.order,
        name:r.name,
        field:"reps",
      });
    }
  }

  if(!gaps.length)return null;

  return{
    status:"gaps",
    envelope:raw,
    exercises:normalized,
    gaps,
    notImported:extractNotImported(raw),
  };
}

function assembleFreeformProgramDocument(gapResult,gapAnswers){
  if(!gapResult||!gapResult.exercises||!gapAnswers)return null;
  const rows=[],orders=new Map();
  for(let i=0;i<gapResult.exercises.length;i++){
    const row=gapResult.exercises[i];
    const copy={...row};
    // Order is the row's position within its day. Deriving it here rather than
    // trusting the reply keeps a partly numbered envelope from producing two
    // rows that claim the same slot.
    const nextOrder=(orders.get(copy.day)||0)+1;
    orders.set(copy.day,nextOrder);
    copy.order=nextOrder;
    if(copy.sets===undefined){
      const val=gapAnswers[`${i}::sets`];
      const parsedSets=parseSetsInput(val);
      if(parsedSets===null)return null;
      copy.sets=parsedSets;
    }
    if(copy.min===undefined||copy.max===undefined){
      const val=gapAnswers[`${i}::reps`];
      const parsedReps=parseRepsInput(val);
      if(parsedReps===null)return null;
      copy.min=parsedReps.min;
      copy.max=parsedReps.max;
    }
    rows.push(copy);
  }
  return JSON.stringify({
    version:3,
    meta:gapResult.envelope?.meta||{name:t("entry.freeform.source_name")},
    exercises:rows,
  });
}

/* A reply is read as a program the same way a file is:
   1. Fast path: The JSON the prompt asked for, or plain-text export parser.
   2. Gap path: Structured envelope with missing sidecars or absent numeric fields.
   Nothing incomplete reaches parseProgramSource or the program model. */
function parseFreeformProgramReply(text){
  const raw=String(text||"");
  if(!raw.trim()||importUtf8Bytes(raw)>IMPORT_MAX_BYTES)return null;
  const candidates=freeformJsonCandidates(raw);

  for(const candidate of candidates){
    const parsed=parseProgramSource(candidate);
    if(parsed?.exercises?.length){
      let notImported=[];
      try{notImported=extractNotImported(boundedImportJson(candidate.trim()))}catch{}
      return Object.assign(parsed,{status:"complete",notImported});
    }
  }
  const direct=parseProgramSource(raw);
  if(direct?.exercises?.length){
    let notImported=[];
    try{notImported=extractNotImported(boundedImportJson(raw.trim()))}catch{}
    return Object.assign(direct,{status:"complete",notImported});
  }

  for(const candidate of candidates){
    const gapResult=readFreeformGapEnvelope(candidate);
    if(gapResult)return gapResult;
  }
  const directGap=readFreeformGapEnvelope(raw);
  if(directGap)return directGap;

  // A syntax error is not an invalid exercise. Keep them separate so a pasted
  // Markdown-escaped bracket (e.g. \\[) asks for a clean copy, not invented sets.
  // Diagnosis only: parsing here never accepts anything, and nothing is repaired.
  const syntaxBroken=value=>{try{JSON.parse(value);return false}catch{return true}};
  const reason=candidates.some(syntaxBroken)?"invalid_json"
    :candidates.length?"invalid_rows"
    :/^\s*```/.test(raw)?"invalid_json":"no_json";
  return{status:"unreadable",reason};}

/* A repair prompt that names what actually broke. Missing numbers are no longer
   a failure — they go to the gap step — so what is left is structural, and the
   lifter should be able to paste back something more useful than "try again". */
const FREEFORM_REPAIR_KEYS={
  no_json:"entry.freeform.repair_no_json",
  invalid_json:"entry.freeform.repair_invalid_json",
  invalid_rows:"entry.freeform.repair_invalid_rows",
  assemble_failed:"entry.freeform.repair_assemble_failed",
};
function freeformRepairPrompt(){
  return t(FREEFORM_REPAIR_KEYS[entryFreeformFailReason]||FREEFORM_REPAIR_KEYS.no_json)}
/* Everything that has to still be true for a finished clipboard read to belong
   to this interaction. Compared by value, so a reply typed while the read was in
   flight, an edited source, a new stage, the other import door or an import
   review opened by any other route all retire the result. */
function freeformClipboardToken(){
  return{seq:entryFreeformClipboardSeq,epoch:entryFreeformEpoch,mode:importSourceMode(),
    stage:entryFreeformStage,source:entryFreeformInput,reply:entryFreeformReply}}
function freeformClipboardCurrent(token){
  return token.seq===entryFreeformClipboardSeq&&token.epoch===entryFreeformEpoch&&
    token.mode===importSourceMode()&&token.stage===entryFreeformStage&&
    token.source===entryFreeformInput&&token.reply===entryFreeformReply&&!importDraft}

/* The note lives in the markup so a failed read never costs the caret: it is
   written in place rather than through a re-render, which would drop focus off
   the button the lifter just pressed and away from the manual field. */
const FREEFORM_CLIPBOARD_NOTE_KEYS={
  empty:"entry.freeform.clipboard_empty",
  failed:"entry.freeform.clipboard_failed",
  unavailable:"entry.freeform.clipboard_unavailable",
};
const freeformClipboardNoteText=kind=>
  FREEFORM_CLIPBOARD_NOTE_KEYS[kind]?t(FREEFORM_CLIPBOARD_NOTE_KEYS[kind]):"";
function setFreeformClipboardNote(kind){
  entryFreeformClipboardNote=kind||null;
  const el=$("#entryFreeformClipNote");
  if(!el)return;
  el.textContent=freeformClipboardNoteText(kind);
  el.hidden=!kind;
  el.setAttribute("role",kind==="empty"?"status":"alert")}
function setFreeformClipboardBusy(busy){
  const btn=$("#entryFreeformClipboard");
  if(!btn)return;
  btn.disabled=!!busy;
  btn.setAttribute("aria-busy",busy?"true":"false");
  btn.textContent=busy?t("entry.freeform.clipboard_busy"):t("entry.freeform.clipboard_import")}

/* The fast way back from the assistant. Clipboard is transport and nothing
   more: it fills the same reply the textarea fills and presses the same review
   action, so every reply — complete, gapped, prose-wrapped or unreadable — is
   read by exactly the code a typed reply goes through. */
async function importFreeformFromClipboard(){
  if(entryFreeformClipboardBusy)return false;
  const read=navigator.clipboard?.readText;
  if(typeof read!=="function"){setFreeformClipboardNote("unavailable");return false}
  // Started before any bookkeeping so the user-gesture chain that iOS Safari
  // requires for a clipboard read is not spent on our own work first.
  let pending;
  try{pending=navigator.clipboard.readText()}
  catch{setFreeformClipboardNote("failed");return false}
  entryFreeformClipboardSeq++;
  const token=freeformClipboardToken();
  entryFreeformClipboardBusy=true;
  setFreeformClipboardNote(null);
  setFreeformClipboardBusy(true);
  let text=null,failed=false;
  try{text=await pending}catch{failed=true}
  entryFreeformClipboardBusy=false;
  const current=freeformClipboardCurrent(token);
  setFreeformClipboardBusy(false);
  if(!current)return false;
  if(failed){setFreeformClipboardNote("failed");return false}
  if(!String(text||"").trim()){setFreeformClipboardNote("empty");return false}
  // From here it is an ordinary reply. No parsing, no recovery, no telemetry.
  entryFreeformReply=String(text);
  entryFreeformStatus=null;
  entryFreeformFailReason=null;
  setFreeformClipboardNote(null);
  saveFreeformSession();
  startFreeformReview();
  return true}

async function copyFreeformPrompt(){
  const program=freeformProgram();
  if(!program){toast(t("entry.freeform.needs_input"));return false}
  return copyToClipboard(freeformPrompt(program),
    "toast.freeform_prompt_copied","toast.freeform_copy_failed")}
/* The link itself does the navigating — a real anchor survives a standalone
   install where window.open does not. Long prompts are copied in advance via
   the two-tap flow, so navigation never races clipboard writes. */
function openFreeformApp(app,event){
  const program=freeformProgram();
  if(!FREEFORM_APPS[app]||!program){
    event?.preventDefault?.();
    toast(t("entry.freeform.needs_input"));
    return false}
  const prompt=freeformPrompt(program);
  const isLong=prompt.length>FREEFORM_URL_MAX;
  captureEvent("program_import_handoff",{method:app,outcome:"opened",long_prompt:isLong});
  entryFreeformStage=3;
  entryFreeformLastProvider=app;
  saveFreeformSession();
  setTimeout(renderOnboarding,0);
  return true}
function loadFreeformProgram(source){
  pendingImportIo=null;
  captureUnsupportedWorkoutConcepts(source.notImported);
  const draft=buildImportDraft(source,t("entry.freeform.source_name"));
  draft.sourceType="freeform";
  draft.notImported=source.notImported||[];
  draft.originalText=entryFreeformInput;
  draft.fromFirstRun=firstRunOpen();
  draft.onboarding=draft.fromFirstRun||!!$("#onboarding")?.classList.contains("active");
  resetFreeformImport();
  openImportReview(draft);
  return draft}

/** The reply becomes an ordinary import draft: same review, same activation. */
function startFreeformReview(){
  const reply=String(entryFreeformReply||"").trim();
  if(!reply){toast(t("toast.freeform_empty"));return null}
  const source=parseFreeformProgramReply(reply);
  if(!source||source.status==="unreadable"){
    entryFreeformStatus="unreadable";
    entryFreeformFailReason=source?.reason||"no_json";
    captureEvent("program_import_parsed",{source:"freeform",outcome:"unreadable",gap_count:0});
    renderOnboarding();
    toast(t("toast.freeform_unreadable"));
    return null;
  }
  if(source.status==="gaps"){
    entryFreeformGapResult=source;
    entryFreeformGapAnswers={};
    entryFreeformGapErrors.clear();
    captureEvent("program_import_parsed",{source:"freeform",outcome:"gaps",gap_count:source.gaps.length});
    renderOnboarding();
    return null;
  }
  if(!source.exercises?.length){
    entryFreeformStatus="unreadable";
    entryFreeformFailReason="invalid_rows";
    captureEvent("program_import_parsed",{source:"freeform",outcome:"unreadable",gap_count:0});
    toast(t("toast.freeform_unreadable"));
    return null;
  }
  captureEvent("program_import_parsed",{source:"freeform",outcome:"complete",gap_count:0});
  return loadFreeformProgram(source);
}

function submitFreeformGaps(){
  if(!entryFreeformGapResult)return;
  entryFreeformGapErrors.clear();
  const gaps=entryFreeformGapResult.gaps||[];
  for(const gap of gaps){
    const val=entryFreeformGapAnswers[gap.key];
    if(gap.field==="sets"){
      if(parseSetsInput(val)===null)entryFreeformGapErrors.add(gap.key);
    }else if(gap.field==="reps"){
      if(parseRepsInput(val)===null)entryFreeformGapErrors.add(gap.key);
    }
  }
  if(entryFreeformGapErrors.size>0){
    renderOnboarding();
    const firstInvalid=$(".entry__field-input.is-invalid");
    if(firstInvalid)try{firstInvalid.focus()}catch{}
    return;
  }
  const assembledDoc=assembleFreeformProgramDocument(entryFreeformGapResult,entryFreeformGapAnswers);
  const parsed=parseProgramSource(assembledDoc);
  if(!parsed||!parsed.exercises||!parsed.exercises.length){
    entryFreeformStatus="unreadable";
    entryFreeformFailReason="assemble_failed";
    entryFreeformGapResult=null;
    renderOnboarding();
    toast(t("toast.freeform_unreadable"));
    return;
  }
  parsed.notImported=entryFreeformGapResult.notImported||[];
  entryFreeformGapResult=null;
  entryFreeformGapAnswers={};
  loadFreeformProgram(parsed);
}

function renderFreeformGapsStep(){
  const gaps=entryFreeformGapResult.gaps||[];
  const notImported=entryFreeformGapResult.notImported||[];
  let notImportedHtml="";
  if(notImported.length){
    const items=notImported.map(cat=>t(FREEFORM_NOT_IMPORTED_KEYS[cat]||"entry.freeform.not_imported.other_notes")).join(", ");
    notImportedHtml=`<p class="entry__notice entry__notice--info" role="status">${esc(t("entry.freeform.not_imported_notice",{items}))}</p>`;
  }
  const gapRows=gaps.map(gap=>{
    const isSets=gap.field==="sets";
    const val=entryFreeformGapAnswers[gap.key]||"";
    const hasError=entryFreeformGapErrors.has(gap.key);
    const label=isSets
      ?t("entry.freeform.gap_sets_label",{exercise:`${gap.day} · ${gap.name}`})
      :t("entry.freeform.gap_reps_label",{exercise:`${gap.day} · ${gap.name}`});
    const placeholder=isSets?t("entry.freeform.gap_sets_placeholder"):t("entry.freeform.gap_reps_placeholder");
    return `<label class="entry__field"><span>${esc(label)}</span>`+
      `<input type="text" class="entry__field-input${hasError?" is-invalid":""}"${hasError?' aria-invalid="true"':""} data-gap-key="${esc(gap.key)}" value="${esc(val)}" placeholder="${esc(placeholder)}"></label>`;
  }).join("");

  return entryHeading(t("entry.freeform.gaps_title"))+
    `<p class="onb__explain">${esc(t("entry.freeform.gaps_lede"))}</p>`+
    notImportedHtml+
    (entryFreeformGapErrors.size?`<p class="entry__notice entry__notice--warn" role="alert">${esc(t("entry.freeform.gap_error"))}</p>`:"")+
    `<div class="entry__gaps-list">${gapRows}</div>`+
    `<div class="btnrow btnrow--primary-first"><button type="button" class="btn btn--cta" id="entryFreeformSubmitGaps">${esc(t("entry.freeform.gaps_submit"))}</button>`+
    `<button type="button" class="btn btn--steel" id="entryFreeformBackToReply">${esc(t("entry.freeform.back_to_reply"))}</button></div>`;
}

/* What the restore choice needs to state the trade honestly: what this device
   holds, what the file holds, and how much of the file is actually new. */
function importChoiceContext(s,opener,io){
  const have=new Set(state.log.map(r=>r.session));
  return{s,io:io||null,opener,
    inSessions:new Set(s.log.map(r=>r.session)).size,inSets:s.log.length,
    curSessions:have.size,curSets:state.log.length,
    newSessions:new Set(s.log.filter(r=>!have.has(r.session)).map(r=>r.session)).size}}
/* A file from slow storage can still be reading when another is picked. Only
   the latest pick may answer; an earlier read must not reopen the choice. */
let backupFileSelection=0;
async function importJson(e){const f=e.target.files?.[0];if(!f)return;
  const selection=++backupFileSelection;
  try{
    if(Number.isFinite(f.size)&&f.size>BACKUP_MAX_BYTES)throw Error();
    const text=await f.text();
    if(selection!==backupFileSelection)return;
    const s=parseBackupFile(text);
    if(!isImportableState(s))throw Error();
    if(isLegacyBackup(s)){toast(t("toast.backup_legacy"));e.target.value="";return}
    openImportChoice(importChoiceContext(s,e.target))}
  catch{if(selection===backupFileSelection)toast(t("toast.import_invalid"))}
  e.target.value=""}
/* Restoring answers the setup gate it may have arrived through: the lifter now
   has both a program and a history, so there is nothing left for the gate to
   ask. Idempotent, since the Settings door has no gate standing. */
function leaveSetupGates(){
  if(firstRunOpen())closeFirstRun();
  if($("#onboarding")?.classList.contains("active"))closeOnboarding()}
/* The body and the buttons describe the file that is actually in front of the
   lifter. A backup taken before the first workout carries no sessions at all,
   so the session arithmetic is noise and Merge has nothing to add: what the
   file still holds is the program and the settings, and the choice is restore
   it or leave this device alone. */
function openImportChoice(ctx){const d=$("#importChoice");
  const bodyKey=ctx.bodyKey||"dialog.import.body",mergeable=ctx.inSessions>0;
  $("#importChoiceBody").textContent=t(mergeable?bodyKey:`${bodyKey}_nolog`,{curSessions:ctx.curSessions,curSets:ctx.curSets,inSessions:ctx.inSessions,inSets:ctx.inSets,newSessions:ctx.newSessions});
  const active=document.activeElement;
  // The file input itself is never the way back: it is the invisible half of a
  // label button. Whichever door this came through, focus returns to that
  // label — the Settings row stays the fallback for a caller without one.
  const opener=canTakeFocus(active)?active
    :(ctx.opener?.closest?.("label")||$("#importJson")?.closest("label")||$("#dataImportRow"));
  const close=()=>closeModal(d);
  const io=ctx.io||storageIO;
  const onlyBtn=$("#importProgramOnly"),mergeBtn=$("#importMerge");
  if(onlyBtn)onlyBtn.classList.toggle("hidden",!ctx.programOnly);
  if(mergeBtn)mergeBtn.classList.toggle("hidden",!mergeable);
  openModal(d,{initialFocus:$("#importCancel"),returnFocus:opener,onEscape:close});
  let importBusy=false;
  $("#importCancel").onclick=()=>{if(importBusy)return;close();toast(t("toast.import_cancelled"))};
  if(onlyBtn)onlyBtn.onclick=()=>{
    if(importBusy||!ctx.programOnly)return;
    // Nothing has been written, so this is still just a change of screen.
    close();ctx.programOnly()};
  $("#importReplace").onclick=async()=>{
    if(importBusy)return;importBusy=true;
    const discardDraftRaw=readDraftRaw();
    try{const result=await replaceImportedState(ctx.s,io,{discardDraftRaw});
      if(result.localOk||result.idbOk){close();resetDraftSessionState();day=days()[0]||"Day 1";syncLang();leaveSetupGates();render();toast(tOne("toast.imported_sessions",ctx.inSessions,{sessions:ctx.inSessions}))}}
    finally{importBusy=false}};
  $("#importMerge").onclick=async()=>{
    if(importBusy)return;importBusy=true;
    try{const result=await mergeImportedLog(ctx.s,io);
      if(result.added===0){close();toast(t("toast.nothing_to_merge"));return}
      if(result.localOk||result.idbOk){close();leaveSetupGates();render();toast(t("toast.merged_sessions",{n:result.added,sessions:tp(result.added,"session")}))}}
    finally{importBusy=false}}}
function mergeLog(s){return mergeImportedLog(s)}

