      label:t("entry.birth_date.year"),value:String(ENTRY_BIRTH_YEARS[type.index]),errorKey:"validation.date",
      parse:raw=>entryStrictInteger(raw,ENTRY_BIRTH_YEARS[0],ENTRY_BIRTH_YEARS.at(-1)),
