  reconcile:async()=>{const read=DraftStore.readCanonicalStatus();return read.status==="ok"?reconcileV2Checkpoint(read,day):read},
  clear:clearDraft,
  recovery:()=>draftUiRecovery,
  retryRecovery:retryDraftRecovery,
